window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[288]={"id":"288","numero":288,"titre":"Pathologie hémorroïdaire","objectifs":[{"id":"288-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition des hémorroïdes","contenu":"<div class=\"notion-course\"><p><span>Les</span> <span>hémorroïdes</span> sont des <span>structures anatomiques vasculaires de l'anus, normalement présentes chez l'individu sain</span> : ce sont des structures <strong>physiologiques</strong>, et non une maladie en soi.</p>\n\n      <h5>Composition d'une hémorroïde</h5>\n      <ul>\n        <li><span><span class=\"nc-pink nc-bold\">Lacs veineux</span></span>.</li>\n        <li><span><span class=\"nc-pink nc-bold\">Petites artérioles sous-muqueuses</span></span>.</li>\n        <li><span><span class=\"nc-pink nc-bold\">Intense réseau anastomotique</span></span> = véritable <span><span class=\"nc-pink nc-bold\">shunt artério-veineux</span></span>.</li>\n        <li><span><span class=\"nc-blue_bg nc-bold\">Tissu de soutien</span></span> : fibres musculaires lisses et tissu collagène, qui ancrent la structure.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">⚠️ La <span><span class=\"nc-orange_bg\">laxité du matériel d'ancrage avec le</span> <span class=\"nc-orange_bg nc-bold\">vieillissement</span></span> <span class=\"nc-orange_bg\">peut conduire à une </span><strong><span class=\"nc-orange_bg\">procidence / saillie</span></strong><span class=\"nc-orange_bg\"> des hémorroïdes</span> — point de départ de la maladie hémorroïdaire.</div>\n\n      <h5>Deux groupes hémorroïdaires</h5>\n      <ul>\n        <li><strong>Plexus interne</strong> : <span>sus-pectinéal</span>, intra-canalaire (détaillé à l'objectif « Savoir distinguer <span>les</span> hémorroïdes externes et internes »).</li>\n        <li><strong>Plexus externe</strong> : <span>sous-pectinéal</span>, au niveau de la marge anale.</li>\n      </ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://larevue.snfcp.org/la-maladie-hemorroidaire/\" target=\"_blank\" rel=\"noopener noreferrer\">SNFCP · maladie hémorroïdaire, revue 2025</a></li></ul></details>","frequence":0},{"id":"288-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la fréquence de la pathologie hémorroïdaire","contenu":"<div class=\"notion-course\"><p>La pathologie hémorroïdaire est l'<span>affection la plus fréquente en proctologie</span>.</p>\n\n      <h5>Fréquence</h5>\n      <ul>\n        <li>Environ <span>1/3 de la population</span> a eu au moins un symptôme hémorroïdaire au cours de l'année écoulée (et <span>1/3 d'entre eux</span> consultent).</li>\n        <li>Jusqu'à <span>80 % de la population générale</span> serait concernée au moins une fois dans sa vie.</li>\n      </ul>\n\n      <h5><span>Terrain</span></h5>\n      <ul>\n        <li>Peut s'observer à <span>tout âge</span>.</li>\n        <li><span>Sans prédisposition féminine ni masculine</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">⚠️ <strong>Maladie bénigne, mais vigilance carcinologique.</strong> La <span>maladie hémorroïdaire</span> <span class=\"nc-green_bg\">ne </span><span><span class=\"nc-green_bg\">menace</span></span><span class=\"nc-green_bg\"> pas le </span><span><span class=\"nc-green_bg\">pronostic vital</span></span> et <span><span class=\"nc-green_bg\">ne dégénère pas</span></span>. En revanche, <span>les</span> <span>saignements hémorroïdaires</span> peuvent <span>gêner le dépistage du cancer colorectal</span> : un <span>saignement survenant à l'occasion d'une défécation</span> est un <span>signe d'alarme</span> qui impose une <span><span class=\"nc-blue nc-bold\">exploration colorectale</span></span> (attitude à nuancer selon le <span>terrain</span> et le contexte). Discriminant : le <span class=\"nc-yellow_bg\">saignement hémorroïdaire survient classiquement </span><span><span class=\"nc-yellow_bg\">à la fin de la selle</span>, <span class=\"nc-yellow_bg\">non mélangé aux selles</span></span>.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 301 — Tumeur colon - rectum</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://larevue.snfcp.org/la-maladie-hemorroidaire/\" target=\"_blank\" rel=\"noopener noreferrer\">SNFCP · maladie hémorroïdaire, revue 2025</a></li></ul></details>","frequence":0},{"id":"288-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie des hémorroïdes","contenu":"<div class=\"notion-course\"><p>La <span>maladie hémorroïdaire</span> représente l'ensemble des plaintes en lien avec <span>les</span> <span>modifications du tissu hémorroïdaire</span>. On distingue :</p>\n      <ul>\n        <li><span><span class=\"nc-orange_bg\">Crise</span></span> : plaintes de <span>courte durée comportant une composante douloureuse</span>.</li>\n        <li><span><span class=\"nc-orange_bg\">Maladie chronique</span></span> : <span>signes réguliers</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">⚠️ <strong><span class=\"nc-brown_bg\">Pas de corrélation anatomo-clinique</span></strong> : de petites hémorroïdes peuvent être symptomatiques et de grosses hémorroïdes asymptomatiques (même si <span>les</span> symptômes s'accompagnent habituellement d'une modification morphologique).</div>\n\n      <h5><span>Les</span> deux théories physiopathologiques</h5>\n      <table>\n        <thead>\n          <tr><th>Théorie</th><th>Principe et conséquences</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span>Théorie mécanique</span></td>\n            <td>\n              <strong>Mécanisme :</strong> <span>fragilisation du <span class=\"nc-blue_bg nc-bold\">tissu de soutien</span></span> / matériel d'ancrage des hémorroïdes internes.<br>\n              <strong><span>Facteurs de risque</span> évoqués :</strong> <span><span class=\"nc-blue_bg\">accouchement</span></span> ; <span><span class=\"nc-blue_bg\">long temps passé à la selle</span></span> ; <span><span class=\"nc-blue_bg\">efforts de poussée</span></span> (<span>dyschésie</span>) ; <span>selles dures</span>.<br>\n              <strong>Conséquence thérapeutique :</strong> la prise en charge vise à renforcer / repositionner le tissu hémorroïdaire (traitements instrumentaux, certains traitements chirurgicaux).\n            </td>\n          </tr>\n          <tr>\n            <td><span>Théorie vasculaire</span></td>\n            <td>\n              <strong>Principe :</strong> la maladie s'apparente à une <span>insuffisance veineuse</span> — argumentée par l'<span>augmentation de taille du tissu en fin de grossesse</span> et l'efficacité à court terme des <span>veinotoniques</span>.<br>\n              <strong>Limites :</strong> <span>les</span> <span>hémorroïdes ne sont pas des veines</span> (pas de valvules conniventes) ; les <span>saignements rouges de la <span class=\"nc-orange_bg\">crise</span> ne sont pas veineux</span>.\n            </td>\n          </tr>\n        </tbody>\n      </table></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://larevue.snfcp.org/la-maladie-hemorroidaire/\" target=\"_blank\" rel=\"noopener noreferrer\">SNFCP · maladie hémorroïdaire, revue 2025</a></li></ul></details>","frequence":0},{"id":"288-4","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir distinguer les hémorroïdes externes et internes","contenu":"<div class=\"notion-course\"><img src=\"../assets/images/288/anatomie-canal-anal.png\" alt=\"Schéma anatomique du canal anal : sphincters interne et externe, hémorroïdes internes (sus-pectinéales) et externes (sous-pectinéales), ligne pectinée, ligament de Parks\" style=\"max-width:100%;height:auto;border-radius:8px;margin:.5rem 0;\">\n\n      <p>Le repère anatomique central est la <span><span class=\"nc-yellow_bg\">ligne pectinée</span></span> : zone de transition entre deux épithéliums, située au milieu du canal anal. Le <strong>sphincter interne se termine en regard de la <span class=\"nc-yellow_bg\">ligne pectinée</span></strong>.</p>\n\n      <h5>Plexus externe <span>vs</span> plexus interne</h5>\n      <table>\n        <thead>\n          <tr><th>Critère</th><th>Plexus externe</th><th>Plexus interne</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Localisation</strong></td>\n            <td>Péri-anal, immédiatement sous-cutané, dans <span>les</span> <span><span class=\"nc-purple nc-bold\">plis radiés de l'anus</span></span>.</td>\n            <td>Intra-canalaire, en <span>sus-pectinéal</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span>Histologie</span></strong></td>\n            <td><span><span class=\"nc-purple nc-bold\">Épithélium de type malpighien</span></span>.</td>\n            <td><span><span class=\"nc-purple nc-bold\">Épithélium de type intestinal</span></span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Vascularisation</strong></td>\n            <td><span>Artère rectale inférieure</span>.</td>\n            <td>Branches de l'<span>artère rectale supérieure</span> — 3 paquets : <span>antéro-droit, postéro-droit, latéral gauche</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Visible ?</strong></td>\n            <td>Non, sauf en cas de complication (<span>thrombose externe</span>).</td>\n            <td>Uniquement en <span>anuscopie</span> (sauf <span><span class=\"nc-red nc-bold\">prolapsus</span> extériorisé</span>).</td>\n          </tr>\n          <tr>\n            <td><strong>Palpable ?</strong></td>\n            <td>Non, sauf en cas de <span><span class=\"nc-red nc-bold\">thrombose hémorroïdaire externe</span></span>.</td>\n            <td>Non.</td>\n          </tr>\n          <tr>\n            <td><strong>Complications</strong></td>\n            <td><span><span class=\"nc-red nc-bold\">Thrombose hémorroïdaire externe</span></span> — <strong><span class=\"nc-red nc-bold\">seule complication des hémorroïdes externes</span></strong>.</td>\n            <td>\n              <strong><span class=\"nc-red nc-bold\">Hémorragie</span> :</strong> <span>épistaxis anal</span> ;<br>\n              <strong><span class=\"nc-red nc-bold\">Prolapsus</span> / <span class=\"nc-red nc-bold\">procidence</span> :</strong> <span>extériorisation</span> ;<br>\n              <strong><span class=\"nc-red nc-bold\">Crise hémorroïdaire</span> :</strong> <span><span class=\"nc-orange_bg\">crise</span> fluxionnaire</span> ;<br>\n              <strong><span class=\"nc-red nc-bold\">Thrombose hémorroïdaire interne</span> :</strong> <span>beaucoup plus rare</span>.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p>À noter : le plexus interne forme des <span>renflements-coussinets (paquets hémorroïdaires)</span> et <span>participe au tonus de repos de la partie haute du canal anal et à la continence fine</span>.</p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://larevue.snfcp.org/la-maladie-hemorroidaire/\" target=\"_blank\" rel=\"noopener noreferrer\">SNFCP · maladie hémorroïdaire, revue 2025</a></li></ul></details>","frequence":0},{"id":"288-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’une thrombose hémorroïdaire","contenu":"<div class=\"notion-course\"><p>La <span><span class=\"nc-red nc-bold\">thrombose hémorroïdaire externe</span></span> est la <strong><span class=\"nc-red nc-bold\">seule complication des hémorroïdes externes</span></strong>. Son diagnostic est <strong>clinique</strong> : l'examen clinique suffit.</p>\n\n      <h5>Facteurs déclenchants (inconstants)</h5>\n      <ul>\n        <li><span>Exercice physique</span>, notamment le cyclisme.</li>\n        <li><span><span class=\"nc-brown_bg\">Contrainte mécanique</span></span> locale.</li>\n        <li><span><span class=\"nc-brown_bg\">Traumatisme</span></span> — notamment l'accouchement.</li>\n      </ul>\n\n      <h5>Douleur anale aiguë +++</h5>\n      <ul>\n        <li>Installation <span><span class=\"nc-red nc-bold\">brutale</span></span>.</li>\n        <li>Intensité <span>intense</span>.</li>\n        <li>Type : associe à divers degrés une <span><span class=\"nc-red nc-bold\">sensation de cuisson</span>, de <span class=\"nc-red nc-bold\">tension</span> et une <span class=\"nc-red nc-bold\">douleur vive</span></span>.</li>\n        <li><span><span class=\"nc-green nc-bold\">Peu ou pas rythmée par la défécation</span></span> — contrairement à la <span class=\"nc-orange_bg\">fissure anale</span>.</li>\n        <li><span><span class=\"nc-green nc-bold\">Rarement insomniante</span></span> — contrairement aux suppurations.</li>\n      </ul>\n\n      <h5>Autres symptômes</h5>\n      <ul>\n        <li>Perception d'une <span>boule à l'anus</span>.</li>\n        <li><span class=\"nc-blue_bg\">Saignements </span><span><span class=\"nc-blue_bg\">tardifs et inconstants</span></span> — notamment en cas de fistulisation spontanée, avec alors diminution de la douleur.</li>\n      </ul>\n\n      <h5>Examen clinique</h5>\n      <ul>\n        <li><span><span class=\"nc-yellow_bg\">Tuméfaction ferme mais non dure</span>, <span class=\"nc-yellow_bg\">bleutée</span>, <span class=\"nc-yellow_bg\">douloureuse à la palpation</span></span>, siégeant dans <span>les</span> <span><span class=\"nc-purple nc-bold\">plis radiés de l'anus</span></span>.</li>\n        <li>Réaction <span>œdémateuse</span> souvent associée — elle <span class=\"nc-blue_bg\">peut masquer le </span><span><span class=\"nc-blue_bg\">thrombus</span></span><span class=\"nc-blue_bg\"> si elle est importante</span> (surtout en cas de <span>grossesse</span> ou de post-partum).</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">⚠️ <span>TR et anuscopie à éviter</span> : ils sont <span class=\"nc-green nc-bold\">douloureux</span> dans cette situation, sauf en cas de doute sur un <span>diagnostic différentiel</span> ou surajouté. <span>Les</span> <strong>examens complémentaires ne sont pas nécessaires</strong> au diagnostic.</div>\n\n      <h5><span class=\"nc-red nc-bold\">Thrombose hémorroïdaire interne</span> (beaucoup plus rare)</h5>\n      <ul>\n        <li><span class=\"nc-blue_bg\">Douleur anale aiguë perçue comme </span><span><span class=\"nc-blue_bg\">« interne »</span></span>.</li>\n        <li><span class=\"nc-green_bg\">Marge anale normale</span> ; <span>TR très douloureux percevant le thrombus</span>.</li>\n        <li><span>Anuscopie</span> : confirme le diagnostic.</li>\n      </ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://larevue.snfcp.org/la-maladie-hemorroidaire/\" target=\"_blank\" rel=\"noopener noreferrer\">SNFCP · maladie hémorroïdaire, revue 2025</a></li></ul></details>","frequence":1},{"id":"288-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les manifestations cliniques les plus fréquentes des hémorroïdes internes","contenu":"<div class=\"notion-course\"><p>Trois grandes manifestations peuvent s'associer de manière <strong>aiguë ou chronique</strong> : <span><span class=\"nc-red nc-bold\">hémorragie</span></span>, <span><span class=\"nc-red nc-bold\">prolapsus</span> / <span class=\"nc-red nc-bold\">procidence</span></span> et <span>douleurs</span> (<span class=\"nc-orange_bg\">crise</span> fluxionnaire, <em>détaillée à l'objectif « Connaître <span>les</span> autres manifestations possibles des hémorroïdes internes »</em>).</p>\n\n      <h5>Hémorragies hémorroïdaires (« épistaxis anal »)</h5>\n      <ul>\n        <li><strong>Horaire</strong> : contemporaines de la défécation ou au décours immédiat.</li>\n        <li><strong>Couleur</strong> : <span><span class=\"nc-blue_bg\">sang rouge rutilant</span>, <span class=\"nc-blue_bg\">vif</span></span> (origine artériolaire), habituellement <strong><span class=\"nc-red nc-bold\">non mélangé aux matières</span></strong>.</li>\n        <li><strong>Abondance</strong> : souvent faible, au goutte-à-goutte (rarement giclant), souvent <span>surestimée par les patients</span>.</li>\n      </ul>\n\n      <h5><span class=\"nc-red nc-bold\">Prolapsus</span> / <span class=\"nc-red nc-bold\">procidence</span></h5>\n      <ul>\n        <li><strong>Mécanisme</strong> : <span><span class=\"nc-blue_bg\">laxité du tissu conjonctif sous-muqueux</span></span><span class=\"nc-blue_bg\"> des hémorroïdes internes</span> — peut intéresser <span>1 paquet</span> (surtout antérieur chez la femme), <span>3 paquets</span>, voire être <span>circonférentiel</span>.</li>\n        <li><span>Extériorisation des hémorroïdes internes</span> par l'orifice anal — <span class=\"nc-red nc-bold\">lors de la défécation</span>, parfois <span class=\"nc-red nc-bold\">en permanence</span>.</li>\n        <li><span class=\"nc-blue_bg\">Gêne mécanique</span> : sensation de boule sortante lors des <span class=\"nc-blue_bg\">efforts de </span><span><span class=\"nc-blue_bg\">poussée</span></span>.</li>\n        <li>Dans <span>les</span> formes fréquentes ou permanentes (<span>grade</span> 3-4) : <span><span class=\"nc-blue_bg\">prurit</span></span>, <span class=\"nc-blue_bg\">suintement</span>, <span class=\"nc-blue_bg\">brûlures anales</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\">⚠️ Le <strong><span><span class=\"nc-blue_bg\">prurit</span></span> n'est pas considéré comme un symptôme hémorroïdaire</strong> : il ne constitue pas une indication de traitement instrumental ou chirurgical.</div>\n\n      <h5><span>Classification</span> de Goligher (degré de <span class=\"nc-red nc-bold\">procidence</span>)</h5>\n      <table>\n        <thead>\n          <tr><th><span>Grade</span></th><th>Degré de <span class=\"nc-red nc-bold\">procidence</span></th><th>Réintégrable dans le canal anal ?</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Grade</span> 1</strong></td>\n            <td>Hémorroïdes internes <strong>non prolabées</strong>, mais <span>congestives</span> et/ou <span>hémorragiques</span>.</td>\n            <td>Pas de prolapsus.</td>\n          </tr>\n          <tr>\n            <td><strong><span>Grade</span> 2</strong></td>\n            <td>Hémorroïdes internes prolabées (<span class=\"nc-blue_bg\">procidence dans la lumière de l'anuscope</span>).</td>\n            <td>Réintègrent <strong>spontanément</strong> le canal anal.</td>\n          </tr>\n          <tr>\n            <td><strong><span>Grade</span> 3</strong></td>\n            <td>Hémorroïdes internes prolabées (extériorisées lors des poussées).</td>\n            <td>Grade III : <span class=\"nc-red nc-bold\">prolapsus</span> nécessitant une réduction manuelle ; le grade II se réduit spontanément.</td>\n          </tr>\n          <tr>\n            <td><strong><span>Grade</span> 4</strong></td>\n            <td>Hémorroïdes internes prolabées, visibles à l'extérieur de l'anus sans anuscope.</td>\n            <td><span><span class=\"nc-red nc-bold\">Non réintégrables</span></span> — <span><span class=\"nc-red nc-bold\">rupture</span></span><span class=\"nc-red nc-bold\"> totale du l</span><span><span class=\"nc-red nc-bold\">iga</span></span><span class=\"nc-red nc-bold\">ment de Parks</span>.</td>\n          </tr>\n        </tbody>\n      </table></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://larevue.snfcp.org/la-maladie-hemorroidaire/\" target=\"_blank\" rel=\"noopener noreferrer\">SNFCP · maladie hémorroïdaire, revue 2025</a></li></ul></details>","frequence":3},{"id":"288-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître le diagnostic différentiel des hémorroïdes internes","contenu":"<div class=\"notion-course\"><p>Message clé : le <span>saignement hémorroïdaire est aspécifique</span>. <span>Aucun élément symptomatique</span> ne permet d'attribuer avec certitude un saignement à une origine hémorroïdaire.</p>\n\n      <h5>Quand évoquer un autre diagnostic</h5>\n      <ul>\n        <li><span><span class=\"nc-red_bg\">Saignements indépendants de la défécation</span></span> : possibles, mais doivent faire évoquer un autre diagnostic.</li>\n        <li><span>Saignements colorant les selles</span> : doivent également faire évoquer une autre cause — notamment un <span>cancer colorectal</span> ou une <span>MICI</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">🚩 Un <span>saignement survenant à l'occasion d'une défécation</span> est un signe d'alarme imposant une <span><span class=\"nc-blue nc-bold\">exploration colorectale</span></span> (attitude à nuancer selon le <span>terrain</span> et le contexte clinique). Devant des <span>rectorragies</span>, on ne se contente jamais d'attribuer le saignement aux hémorroïdes : il faut <span>éliminer une cause organique</span>.</div>\n\n      <p>⚠️ La fiche source reste volontairement succincte sur une liste exhaustive de diagnostics différentiels des hémorroïdes internes : le point retenu est le <span>caractère aspécifique du saignement</span> et la <span>nécessité d'éliminer une cause organique</span>.</p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 301 — Tumeur colon - rectum · 282 — <span>MICI</span></em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://larevue.snfcp.org/la-maladie-hemorroidaire/\" target=\"_blank\" rel=\"noopener noreferrer\">SNFCP · maladie hémorroïdaire, revue 2025</a></li></ul></details>","frequence":2},{"id":"288-8","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître le diagnostic différentiel de la thrombose hémorroïdaire externe","contenu":"<div class=\"notion-course\"><p>Le <span>diagnostic différentiel</span> de la thrombose hémorroïdaire externe regroupe <span>les</span> <strong>autres causes de douleur anale aiguë</strong>.</p>\n\n      \n      <table>\n        <thead>\n          <tr><th>Étiologie</th><th>Type de douleur</th><th>Rythme</th><th>Durée</th><th>Signes associés</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"nc-red nc-bold\">Crise hémorroïdaire</span></strong></td>\n            <td>Cuisson.</td>\n            <td>Per- et <span class=\"nc-yellow_bg\">post-défécatoire</span>, <strong><span class=\"nc-yellow_bg nc-bold\">peu durable</span></strong>.</td>\n            <td><span><span class=\"nc-pink nc-bold\">24-72 h</span></span>.</td>\n            <td><span>Œdème</span>, <span class=\"nc-red nc-bold\">procidence</span>, saignement.</td>\n          </tr>\n          <tr>\n            <td><strong>Thrombose hémorroïdaire</strong></td>\n            <td>Douleur intense « exquise ».</td>\n            <td><span class=\"nc-green_bg\">Non rythmée par la selle</span>.</td>\n            <td>Heures à jours.</td>\n            <td><span><span class=\"nc-blue_bg\">Tuméfaction</span></span><span class=\"nc-blue_bg\"> anale douloureuse bleutée bien limitée</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-orange_bg\">Fissure anale</span></strong></td>\n            <td>Brûlure.</td>\n            <td>Per- et <span class=\"nc-yellow_bg\">post-défécatoire</span> <strong><span class=\"nc-yellow_bg nc-bold\">durable</span></strong> (persiste plusieurs heures).</td>\n            <td>Semaines.</td>\n            <td>Saignement.</td>\n          </tr>\n          <tr>\n            <td><strong><span>Abcès</span></strong></td>\n            <td><span class=\"nc-red nc-bold\">Tension</span>, douleur pongitive.</td>\n            <td>\n              <strong><span class=\"nc-red nc-bold\">Positionnel de </span><span><span class=\"nc-red nc-bold\">contact</span></span> :</strong> augmentée au toucher / appui ;<br>\n              <strong><span><span class=\"nc-red nc-bold\">Inflammatoire</span></span> :</strong> insomniante.\n            </td>\n            <td>Récente (quelques heures), <span class=\"nc-red nc-bold\">continue</span>.</td>\n            <td><span>Tuméfaction</span> périanale mal limitée, <span class=\"nc-blue_bg\">rouge mais non bleutée</span>, <span class=\"nc-blue_bg\">halo érythémateux</span>, <span><span class=\"nc-orange_bg\">dysurie</span></span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Fécalome / Cancer</strong></td>\n            <td>Épreintes.</td>\n            <td><span class=\"nc-yellow_bg\">Avant la selle</span> (<span class=\"nc-yellow_bg\">douleurs expulsives</span>).</td>\n            <td>Jours.</td>\n            <td><span class=\"nc-red_bg\">Suintements</span>, <span class=\"nc-red_bg\">incontinence</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Herpès</strong></td>\n            <td><span class=\"nc-brown_bg\">Brûlures intenses</span>.</td>\n            <td><span class=\"nc-red nc-bold\">Péri-anales en quadrant</span>.</td>\n            <td>Jours.</td>\n            <td><span class=\"nc-blue_bg\">Lésions ulcérées et érosives périanales</span>, <span><span class=\"nc-orange_bg\">dysurie</span></span>, <span class=\"nc-orange_bg\">hyperesthésie régionale</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Proctalgie fugace</strong></td>\n            <td>Crampe intense.</td>\n            <td>Début brutal, sans facteur déclenchant franc.</td>\n            <td>Minutes (parfois nocturne).</td>\n            <td>Aucun.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Focus — la <span class=\"nc-orange_bg\">fissure anale</span> (<span>diagnostic différentiel</span> principal)</h5>\n      <p>Le diagnostic est évoqué devant une <strong>triade</strong> :</p>\n      <ul>\n        <li><span>Ulcération épithéliale en forme de raquette</span> à la partie basse du canal anal, <strong>postérieure dans <span>75 %</span> des cas</strong> (plus rarement antérieure ou bipolaire).</li>\n        <li><span>Hypertonie du sphincter interne</span> (sphincter contracté au repos, responsable de la douleur).</li>\n        <li><span>Douleur typique en 3 temps</span> : déclenchée par le passage des selles → <span>rémission</span> transitoire de quelques secondes à minutes → reprise douloureuse plus ou moins prolongée (peut durer quelques heures).</li>\n      </ul>\n      <p>Devant une forme atypique (fissure indolore, latérale, absence de contracture sphinctérienne), il faut évoquer :</p>\n      <ul>\n        <li><span>Ulcération</span> de la <span>maladie de Crohn</span>.</li>\n        <li><span><span class=\"nc-orange_bg\">Carcinome épidermoïde</span> de l'anus</span> (plus rarement une hémopathie maligne).</li>\n        <li><span>Infection sexuellement transmissible</span> : <span>syphilis</span>, <span>VIH</span>, <span>tuberculose</span>, <span>chlamydiae</span>, <span>herpès simplex</span>.</li>\n        <li><span>Traumatisme</span> (valeur du contexte).</li>\n        <li><span>Séquelle de radiothérapie</span> (valeur du contexte).</li>\n        <li><span>Maladie de système</span> : <span>maladie de Behçet</span>, <span>granulomatose de Wegener</span>.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 282 — <span>MICI</span></em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://larevue.snfcp.org/la-maladie-hemorroidaire/\" target=\"_blank\" rel=\"noopener noreferrer\">SNFCP · maladie hémorroïdaire, revue 2025</a></li></ul></details>","frequence":0},{"id":"288-9","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les autres manifestations possibles des hémorroïdes internes","contenu":"<div class=\"notion-course\"><h5><span class=\"nc-red nc-bold\">Anémie ferriprive par saignement chronique</span></h5>\n      <ul>\n        <li><span>Anémie ferriprive</span> liée à un saignement hémorroïdaire chronique : <span>très rare</span>.</li>\n        <li>Doit faire <span>éliminer les autres causes d'anémie ferriprive</span> avant de l'attribuer aux hémorroïdes.</li>\n      </ul>\n\n      <h5><span class=\"nc-orange_bg\">Crise</span> fluxionnaire (hémorroïdaire)</h5>\n      <ul>\n        <li>Regroupe <span>toutes les douleurs causées par une hémorroïde interne, <span class=\"nc-yellow_bg\">hors thrombose</span></span> — y compris <span><span class=\"nc-blue nc-bold\">sensation</span> de <span class=\"nc-blue nc-bold\">chaleur</span> et <span class=\"nc-blue nc-bold\">pesanteur</span> <span class=\"nc-blue nc-bold\">périnéale</span></span>.</li>\n        <li>Diagnostic posé <span>après élimination d'une pathologie alternative</span> (notamment <span>fissure ou suppuration</span>).</li>\n        <li><span>FR déclenchants</span> (inconstants) : <span><span class=\"nc-blue nc-bold\">diarrhée</span></span>, <span><span class=\"nc-blue nc-bold\">constipation</span></span>, <span><span class=\"nc-blue nc-bold\">effort de type dyschésie</span></span>, <span class=\"nc-blue nc-bold\">excès de table</span> (<span>alcool</span>, <span>plats épicés</span>).</li>\n        <li><span>Facteur aggravant</span> : <span>passage à la selle</span>, <span><span class=\"nc-red_bg\">exercice physique</span></span>.</li>\n        <li>Durée moyenne : <span><span class=\"nc-pink nc-bold\">24-72 h</span></span>.</li>\n        <li><span>Examen endoscopique</span> : <span class=\"nc-blue_bg\">aspect congestif</span>, œdémateux, <span class=\"nc-blue_bg\">parfois un semis de microthromboses</span>.</li>\n      </ul>\n\n      <h5><span class=\"nc-red nc-bold\">Thrombose hémorroïdaire interne</span></h5>\n      <ul>\n        <li>Beaucoup plus rare que la thrombose hémorroïdaire externe (sémiologie décrite à l'objectif « Connaître <span>les</span> modalités du diagnostic d'une thrombose hémorroïdaire »).</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 301 — Tumeur colon - rectum · 213 — Anémie</em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://larevue.snfcp.org/la-maladie-hemorroidaire/\" target=\"_blank\" rel=\"noopener noreferrer\">SNFCP · maladie hémorroïdaire, revue 2025</a></li></ul></details>","frequence":2},{"id":"288-10","rang":"A","rubrique":"Contenu multimédia","titre":"Photographies d’hémorroïdes externes et hémorroïdes internes prolabées","contenu":"<div class=\"notion-course\"><ul><li>Les photographies conservées comparent hémorroïdes externes et hémorroïdes internes prolabées. Repère anatomique : <span class=\"nc-yellow_bg\">ligne pectinée</span> ; les hémorroïdes internes sont sus-pectinéales, les externes sous-pectinéales.</li><li>Une photographie fixe ne renseigne pas à elle seule sur la réduction spontanée ou manuelle : le grade de Goligher nécessite l’histoire clinique et l’examen en poussée.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://larevue.snfcp.org/la-maladie-hemorroidaire/\" target=\"_blank\" rel=\"noopener noreferrer\">SNFCP · maladie hémorroïdaire, revue 2025</a></li></ul></details>","frequence":0,"liens":[{"href":"https://radiologyassistant.nl/abdomen/rectum","label":"Radiology Assistant — Rectum"},{"href":"https://radiopaedia.org/articles/rectum","label":"Radiopaedia : Rectum"},{"href":"https://radiopaedia.org/cases/rectal-anatomy-illustrations?lang=gb","label":"Radiopaedia : Rectal anatomy illustrations"}]},{"id":"288-11","rang":"A","rubrique":"Contenu multimédia","titre":"Photographies de thrombose hémorroïdaire","contenu":"<div class=\"notion-course\"><ul><li>La photographie illustre une thrombose hémorroïdaire : tuméfaction <span class=\"nc-yellow_bg\">bleutée</span> douloureuse de la marge anale, parfois entourée d’œdème.</li><li>Distinguer un abcès, une fissure et un prolapsus polythrombosé. Le caractère <span class=\"nc-green nc-bold\">douloureux</span>, l’ancienneté et le contexte guident traitement médical et éventuel geste local.</li></ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://larevue.snfcp.org/la-maladie-hemorroidaire/\" target=\"_blank\" rel=\"noopener noreferrer\">SNFCP · maladie hémorroïdaire, revue 2025</a></li></ul></details>","frequence":0},{"id":"288-12","rang":"B","rubrique":"Etiologie","titre":"Connaître les principaux facteurs favorisant la pathologie hémorroïdaire","contenu":"<div class=\"notion-course\"><h5>Facteurs favorisants principaux</h5>\n      <ul>\n        <li><span><span class=\"nc-blue_bg\">Troubles du transit intestinal</span></span>, en particulier la <span>dyschésie</span>.</li>\n        <li><span>3ᵉ trimestre de grossesse</span>.</li>\n        <li><span>Accouchement</span>.</li>\n        <li><span><span class=\"nc-blue_bg\">Post-partum immédiat</span></span>.</li>\n      </ul>\n\n      <h5>Facteurs discutés (non établis)</h5>\n      <ul>\n        <li><span>Antécédents familiaux</span>.</li>\n        <li><span>Alimentation épicée</span>.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 283 — <span>Constipation</span></em></p></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://larevue.snfcp.org/la-maladie-hemorroidaire/\" target=\"_blank\" rel=\"noopener noreferrer\">SNFCP · maladie hémorroïdaire, revue 2025</a></li></ul></details>","frequence":0},{"id":"288-13","rang":"A","rubrique":"Prise en charge","titre":"Connaître les grands principes de la prise en charge médicamenteuse et non médicamenteuse","contenu":"<div class=\"notion-course\"><h5><span>Règles hygiéno-diététiques</span> (traitement non <span>médicamenteux</span>)</h5>\n      <ul>\n        <li><span class=\"nc-yellow_bg\">Lutter contre la </span><span><span class=\"nc-yellow_bg\">constipation chronique</span></span> ++ : limite l'installation de la maladie, résout <span>les</span> symptômes et prévient récidives et complications.</li>\n        <li><span class=\"nc-green_bg\">Alimentation riche en </span><strong><span class=\"nc-green_bg\">fibres solubles</span></strong> : graines de lin, graines de chia, psyllium blond.</li>\n        <li><span>Laxatifs doux</span> en cas de <span>constipation</span> : <strong><span class=\"nc-pink nc-bold\">mucilage</span></strong> ou <strong><span class=\"nc-pink nc-bold\">macrogol</span></strong>.</li>\n      </ul>\n      <div class=\"callout callout-warn\">❌ <span>Les</span> <strong>régimes d'exclusion alimentaire n'ont pas d'efficacité</strong>.</div>\n\n      <h5>Traitement <span>médicamenteux</span></h5>\n      <p>Utilisation <strong>ponctuelle</strong> lors des épisodes <span class=\"nc-green nc-bold\">douloureux</span>, en <strong>cure courte</strong> — ce n'est pas le traitement des formes chroniques.</p>\n      <ul>\n        <li><span>Antalgiques</span> et <span>AINS</span>.</li>\n        <li><span>Veinotonique</span> (diosmine) : efficacité démontrée, diminue l'intensité et la durée des symptômes.</li>\n        <li><span><span class=\"nc-pink_bg\">Topiques locaux</span></span> : <span><span class=\"nc-green nc-bold\">émollients</span></span>, analgésiques, anti-inflammatoires, anti-<span>œdème</span>, favorisant la cicatrisation.</li>\n      </ul>\n\n      <h5>Traitement instrumental</h5>\n      <p>Traitement de fond de la <strong>maladie hémorroïdaire interne</strong>, réalisé en consultation spécialisée <span class=\"nc-green_bg\">à travers un anuscope</span>, <strong>en dehors des poussées</strong>. Il est appliqué <strong>sur la muqueuse rectale au-dessus du tissu hémorroïdaire</strong> (et non sur <span>les</span> hémorroïdes elles-mêmes) — la <span>muqueuse rectale est dépourvue de sensibilité thermo-algésique</span>. Ce <strong>n'est pas un traitement préventif de la thrombose</strong>.</p>\n      <table>\n        <thead>\n          <tr><th>Technique</th><th>Type</th><th>Particularité</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span><span class=\"nc-blue_bg\">Ligature élastique</span></span></td>\n            <td><span>Ischémique</span></td>\n            <td><strong>Meilleur compromis bénéfice / risque</strong> ; <span>contre-indiquée sous anticoagulants ou double anti-agrégation</span>.</td>\n          </tr>\n          <tr>\n            <td><span>Sclérose</span></td>\n            <td>Chimique</td>\n            <td>Injection d'un produit sclérosant <span>2 cm au-dessus de la <span class=\"nc-yellow_bg\">ligne pectinée</span></span>.</td>\n          </tr>\n          <tr>\n            <td><span>Photocoagulation infrarouge</span></td>\n            <td>Thermique</td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><span>Coagulation bipolaire</span></td>\n            <td>Thermique</td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><span>Cryothérapie</span></td>\n            <td>Thermique</td>\n            <td>—</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>Bénéfice important dans ≥ <span>3/4 des cas</span> ; efficacité décroissante avec le <span>suivi</span> → à <strong>répéter</strong> (<span>2-4 fois</span> en moyenne, environ tous <span>les</span> mois). Complications rares : <span>saignement sur chute d'escarre</span> (surtout après l<span>iga</span>ture), <span><span class=\"nc-red nc-bold\">infections</span></span> (surtout après <span><span class=\"nc-blue_bg\">sclérose</span></span>).</p>\n\n      <h5>Traitement chirurgical</h5>\n      <p>Acte réalisé sous <span>anesthésie générale, <span class=\"nc-blue_bg\">péridurale ou locorégionale</span></span>.</p>\n      <ul>\n        <li><span><span class=\"nc-pink_bg\">Hémorroïdectomie</span></span> (résection) : <strong>traitement de référence en efficacité</strong>, mais <strong><span class=\"nc-red nc-bold\">plus douloureuse</span></strong>.</li>\n        <li>Techniques de <span>fixation / pexie</span> (mécanique ou thermique : radiofréquence, <span>laser</span>) : plus rapides, <span class=\"nc-green nc-bold\">moins</span> douloureuses, immobilisation plus courte, mais <span><span class=\"nc-red nc-bold\">risque de récidive plus important</span></span>.</li>\n        <li><span>Séquelle fonctionnelle rare (incontinence)</span> : doit être prévenue et <strong>évaluée avant le geste</strong>.</li>\n      </ul>\n\n      <h5>Escalade thérapeutique selon le <span>grade</span> de Goligher</h5>\n      <p>Le traitement est <strong>progressif</strong>, adapté au <span>grade</span> de sévérité : on n'escalade qu'en cas d'échec du palier précédent.</p>\n      <table>\n        <thead>\n          <tr><th>Grade</th><th>1ʳᵉ intention</th><th>Si échec / récidive</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span>Grade</span> I</strong></td>\n            <td><span>RHD</span> + traitement médical.</td>\n            <td>Photocoagulation infrarouge ou <span><span class=\"nc-blue_bg\">sclérose</span></span>, puis l<span>iga</span>ture.</td>\n          </tr>\n          <tr>\n            <td><strong><span>Grade</span> II</strong></td>\n            <td><span>RHD</span> + traitement médical.</td>\n            <td>Photocoagulation, <span><span class=\"nc-blue_bg\">sclérose</span></span> ou <span class=\"nc-blue_bg\">l</span><span><span class=\"nc-blue_bg\">iga</span></span><span class=\"nc-blue_bg\">ture élastique</span>, puis hémorroïdopexie / <span class=\"nc-blue_bg\">hémorroïdectomie</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span>Grade</span> III</strong></td>\n            <td><span>RHD</span> + traitement médical.</td>\n            <td><span class=\"nc-blue_bg\">L</span><span><span class=\"nc-blue_bg\">iga</span></span><span class=\"nc-blue_bg\">ture élastique</span>, puis mucopexie / hémorroïdopexie, voire <span class=\"nc-blue_bg\">hémorroïdectomie</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span>Grade</span> IV</strong></td>\n            <td>Avis chirurgical pour prolapsus irréductible symptomatique ; choix du traitement selon gêne, terrain, traitements antérieurs et préférences. La chirurgie n’est pas une obligation immédiate pour tout grade IV.</td>\n            <td>—</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">📌 Principe général : débuter par <span>les</span> <strong><span>règles hygiéno-diététiques</span> + traitement médical</strong>, puis les <strong>procédés mini-invasifs</strong> (photocoagulation, l<span>iga</span>ture) en cas d'échec ; la <strong><span>chirurgie</span></strong> est réservée aux formes sévères ou compliquées.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 283 — <span>Constipation</span></em></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Adapter le traitement aux symptômes, au prolapsus et aux préférences. Un grade IV ne rend pas obligatoire une chirurgie immédiate chez un patient asymptomatique ou à risque ; avis spécialisé. <span class=\"nc-pink_bg\">AINS</span> selon contre-indications, notamment grossesse, risque rénal et hémorragique.</li></ul></div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://larevue.snfcp.org/la-maladie-hemorroidaire/\" target=\"_blank\" rel=\"noopener noreferrer\">SNFCP · maladie hémorroïdaire, revue 2025</a></li></ul></details>","frequence":3},{"id":"288-14","rang":"A","rubrique":"Prise en charge","titre":"Connaître les quatre règles de préambule thérapeutique","contenu":"<div class=\"notion-course\"><p>Quatre <span>mesures générales</span> encadrent toute prise en charge de la pathologie hémorroïdaire :</p>\n      <ol>\n        <li>Le <span class=\"nc-yellow_bg\">traitement des hémorroïdes doit être </span><span><span class=\"nc-yellow_bg\">réservé aux </span><span><span class=\"nc-yellow_bg\">formes symptomatiques</span></span></span>.</li>\n        <li>C'est un <span>traitement de confort</span> dans la majorité des cas.</li>\n        <li><span>Les</span> <span>traitements médicamenteux</span> sont habituellement <span class=\"nc-red nc-bold\">réservés aux </span><span><span class=\"nc-red nc-bold\">symptômes aigus</span></span><span class=\"nc-red nc-bold\"> et proposés en </span><span><span class=\"nc-red nc-bold\">cure courte</span></span>.</li>\n        <li><span>Les</span> <span>procédés instrumentaux et chirurgicaux</span> constituent le <span class=\"nc-red nc-bold\">traitement de la </span><span><span class=\"nc-red nc-bold\">maladie hémorroïdaire interne</span></span> (prise en charge spécialisée).</li>\n      </ol></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://larevue.snfcp.org/la-maladie-hemorroidaire/\" target=\"_blank\" rel=\"noopener noreferrer\">SNFCP · maladie hémorroïdaire, revue 2025</a></li></ul></details>","frequence":0},{"id":"288-15","rang":"A","rubrique":"Prise en charge","titre":"Connaître le traitement de la thrombose hémorroïdaire externe","contenu":"<div class=\"notion-course\"><p>Le traitement de la <span>thrombose hémorroïdaire externe</span> est une <span>urgence <span class=\"nc-pink_bg\">antalgique</span></span>.</p>\n\n      <h5>Traitement médical</h5>\n      <ul>\n        <li><span>AINS</span> ++.</li>\n        <li><span>Antalgiques</span> de palier 1-2.</li>\n        <li><span>Topiques</span> contenant un <span>anesthésique local</span>.</li>\n        <li><span><span class=\"nc-pink_bg\">Veinotonique</span></span> (niveau de preuve faible).</li>\n        <li><span><span class=\"nc-pink_bg\">Corticoïde en cure courte</span></span> : alternative si <span>contre-indication aux AINS et au traitement chirurgical</span> (notamment en cas de forte composante œdémateuse).</li>\n      </ul>\n\n      <h5>Geste local (≠ <span>chirurgie</span>)</h5>\n      <ul>\n        <li><span>Incision ou excision</span> de la zone thrombosée, réalisée en consultation — préférer l'<span>excision</span> (meilleure efficacité, effet plus durable).</li>\n        <li>Indications : <span><span class=\"nc-pink nc-bold\">d'emblée si la thrombose est vue précocement</span></span>, ou en cas d'<span><span class=\"nc-pink nc-bold\">inefficacité du traitement médical après </span><span><span class=\"nc-pink nc-bold\">24-48 h</span></span></span>.</li>\n        <li><span>Contre-indication</span> : thrombose <span>œdémateuse</span> — risque d'<span>inefficacité et d'<span class=\"nc-red nc-bold\">hémorragie</span></span>.</li>\n      </ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://larevue.snfcp.org/la-maladie-hemorroidaire/\" target=\"_blank\" rel=\"noopener noreferrer\">SNFCP · maladie hémorroïdaire, revue 2025</a></li></ul></details>","frequence":1},{"id":"288-16","rang":"B","rubrique":"Prise en charge","titre":"Connaître les indications du traitement chirurgical","contenu":"<div class=\"notion-course\"><h5>Indications directes à la <span>chirurgie</span></h5>\n      <ul>\n        <li>Anémie ferriprive avec origine hémorroïdaire confirmée après bilan : discuter un traitement efficace selon sévérité et traitements déjà essayés ; ne pas attribuer automatiquement l’anémie aux hémorroïdes.</li>\n        <li><span class=\"nc-red nc-bold\">Prolapsus</span> thrombosé hyperalgique : avis spécialisé rapide, traitement médical et geste éventuel selon examen et évolution ; pas d’opération automatique de toute thrombose.</li>\n        <li>Thromboses hémorroïdaires externes <span>récidivantes</span>.</li>\n        <li><span>Pathologies proctologiques associées</span> nécessitant une intervention chirurgicale.</li>\n        <li>Marisques gênantes après évaluation et demande du patient : exérèse discutée ; leur seule présence n’impose pas une opération.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">📌 Dans l'algorithme par <span>grade de Goligher</span>, le <span>grade IV</span> (<span><span class=\"nc-red nc-bold\">prolapsus</span> irréductible</span>) a pour traitement de référence l'<span><span class=\"nc-pink_bg\">hémorroïdectomie</span></span>.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie</em></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Une marisque isolée ou un saignement ne suffit pas à imposer la chirurgie. Confirmer la cause, évaluer le retentissement et les traitements déjà essayés, puis discuter le geste avec le patient.</li></ul></div></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://larevue.snfcp.org/la-maladie-hemorroidaire/\" target=\"_blank\" rel=\"noopener noreferrer\">SNFCP · maladie hémorroïdaire, revue 2025</a></li></ul></details>","frequence":0},{"id":"288-17","rang":"B","rubrique":"Suivi et / ou pronostic","titre":"Connaître l’évolution spontanée de la thrombose hémorroïdaire externe","contenu":"<div class=\"notion-course\"><h5>Évolutions spontanées possibles</h5>\n      <ul>\n        <li><span><span class=\"nc-green_bg\">Régression lente</span></span><span class=\"nc-green_bg\"> de la crise avec </span><span><span class=\"nc-green_bg\">rémission anatomique complète ad integrum</span></span> en <span><span class=\"nc-pink nc-bold\">5-15 jours</span></span>.</li>\n        <li><span><span class=\"nc-blue_bg\">Fistulisation à la peau</span></span> : se traduit par un <span><span class=\"nc-blue_bg\">saignement minime</span></span> et une régression / sédation des douleurs.</li>\n        <li><span class=\"nc-orange_bg\">Formation possible d'une </span><span><span class=\"nc-orange_bg\">marisque</span></span> : <span>repli mucocutané résiduel</span> lié à la distension cutanée par la thrombose, sans retour à une anatomie normale (<span><span class=\"nc-red nc-bold\">préjudice surtout esthétique</span></span>, rarement une indication de traitement).</li>\n      </ul>\n\n      <h5><span>Pronostic</span></h5>\n      <ul>\n        <li><span>Évolution</span> <span>bénigne dans tous les cas</span> : <span><span class=\"nc-green_bg\">pas de risque embolique</span></span>.</li>\n        <li><span>Complications suppuratives secondaires</span> exceptionnelles.</li>\n        <li><span>Récidives possibles</span>, y compris sur le même site.</li>\n      </ul></div><details class=\"atlas-source-details\"><summary>Sources et actualisations</summary><p>Cours personnel Notion et copies LiSA disponibles ; compléments des collèges et recommandations ci-dessous. Les images d’origine sont conservées (hors schémas SVG retirés à ta demande) et leurs éventuelles limites sont signalées dans les parcours.</p><ul><li><a href=\"https://www.snfge.org/sites/default/files/SNFGE/Formation/dsn_cdu-hge_2022-decembre.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CDU-HGE · Document source national, décembre 2022</a></li><li><a href=\"https://larevue.snfcp.org/la-maladie-hemorroidaire/\" target=\"_blank\" rel=\"noopener noreferrer\">SNFCP · maladie hémorroïdaire, revue 2025</a></li></ul></details>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Thrombose hémorroïdaire externe <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> <span class=\"kw-ttt\">antalgique</span></span></strong></p><p>Geste local (<span class=\"kw-ttt\">excision</span> &gt; incision) <span class=\"kw-clinique\">d'emblée si thrombose vue précocement</span>, ou après <span class=\"kw-clinique\">échec du traitement médical</span> à <span class=\"kw-chiffre\">24-48 h</span> — <span class=\"kw-ci\">contre-indiqué si thrombose œdémateuse</span></p><ul><li>Douleur anale <span class=\"kw-clinique\">brutale et intense</span> ; <span class=\"kw-clinique\">tuméfaction bleutée</span> des <span class=\"kw-clinique\">plis radiés de l'anus</span></li><li>Traitement médical : <span class=\"kw-ttt\">AINS</span> ++, <span class=\"kw-ttt\">antalgiques</span> de palier 1-2, <span class=\"kw-ttt\">topiques anesthésiques</span>, <span class=\"kw-ttt\">veinotonique</span> ; <span class=\"kw-ttt\">corticoïde</span> en cure courte si <span class=\"kw-ci\">CI aux AINS</span></li></ul><p><strong>Saignement à l'occasion d'une défécation <span class=\"q\">— signe d'alarme</span></strong></p><p><span class=\"kw-imagerie\">Exploration colorectale</span> sans retard (à nuancer selon le <span class=\"kw-def\">terrain</span> et le contexte)</p><ul><li><span class=\"kw-alerte\">Saignement survenant à l'occasion d'une défécation</span> = signe d'alarme</li><li>Ne jamais imputer une <span class=\"kw-clinique\">rectorragie</span> aux hémorroïdes sans avoir éliminé une <span class=\"kw-alerte\">cause organique</span></li></ul>","hospit":"<p><strong>Ambulatoire :</strong> prise en charge en règle <span class=\"kw-clinique\">ambulatoire</span> — maladie <span class=\"kw-def\">bénigne</span>, sans <span class=\"kw-alerte\">urgence</span> vitale ni risque <span class=\"kw-etio\">embolique</span>.</p><p><strong>Consultation spécialisée :</strong> <span class=\"kw-ttt\">traitement instrumental</span> réalisé à travers un <span class=\"kw-imagerie\">anuscope</span>, en consultation externe de gastro-entérologie.</p><p><strong>Bloc opératoire :</strong> <span class=\"kw-ttt\">traitement chirurgical</span> sous <span class=\"kw-ttt\">anesthésie générale, péridurale ou locorégionale</span> (formes sévères ou compliquées).</p>","redflags":"<ul><li><span class=\"kw-alerte\">Saignement à l'occasion d'une défécation</span> → <span class=\"kw-imagerie\">exploration colorectale</span> (éliminer un <span class=\"kw-etio\">cancer colorectal</span>)</li><li><span class=\"kw-alerte\">Saignement indépendant de la défécation</span> ou <span class=\"kw-alerte\">colorant / mélangé aux selles</span> → évoquer un <span class=\"kw-etio\">cancer colorectal</span> ou une <span class=\"kw-etio\">MICI</span></li><li><span class=\"kw-alerte\">Anémie ferriprive</span> par saignement chronique → éliminer une autre cause avant de l'attribuer aux hémorroïdes</li><li><span class=\"kw-clinique\">Rectorragie</span> : <span class=\"kw-ci\">ne jamais</span> l'imputer aux hémorroïdes sans avoir <span class=\"kw-alerte\">éliminé une cause organique</span></li><li><span class=\"kw-clinique\">Douleur anale atypique</span> (fissure indolore, latérale, sans hypertonie) → évoquer <span class=\"kw-etio\">maladie de Crohn</span>, <span class=\"kw-etio\">carcinome épidermoïde de l'anus</span>, <span class=\"kw-etio\">IST</span></li></ul>","principes":"<p><strong>4 règles de préambule :</strong> traitement <span class=\"kw-clinique\">réservé aux formes symptomatiques</span> · <span class=\"kw-ttt\">traitement de confort</span> dans la majorité des cas · <span class=\"kw-ttt\">médicaments</span> en <span class=\"kw-ttt\">cure courte</span> sur <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">symptômes aigus</span> · <span class=\"kw-ttt\">procédés instrumentaux et chirurgicaux</span> = traitement de la <span class=\"kw-def\">maladie hémorroïdaire interne</span> (PEC spécialisée). Le traitement est <span class=\"kw-clinique\">progressif, adapté au grade de Goligher</span>.</p><p><strong>Mesures générales <span class=\"q\">— 1re ligne, tous grades</span></strong></p><ul><li>Lutte contre la <span class=\"kw-clinique\">constipation chronique</span> ++ : alimentation riche en <strong>fibres solubles</strong> (lin, chia, psyllium)</li><li><span class=\"kw-ttt\">Laxatifs doux</span> si <span class=\"kw-clinique\">constipation</span> : <span class=\"kw-ttt\">mucilage</span> ou <span class=\"kw-ttt\">macrogol</span></li><li><span class=\"kw-ci\">Régimes d'exclusion alimentaire</span> inefficaces</li></ul><p><strong>Traitement <span class=\"kw-etio\">médicamenteux</span> <span class=\"q\">— <span class=\"kw-clinique\">poussée</span>, cure courte</span></strong></p><ul><li><span class=\"kw-ttt\">Antalgiques</span> et <span class=\"kw-ttt\">AINS</span> ponctuels</li><li><span class=\"kw-ttt\">Veinotonique</span> (diosmine) : diminue intensité et durée des symptômes</li><li><span class=\"kw-ttt\">Topiques locaux</span> : <span class=\"kw-ttt\">émollients</span>, analgésiques, anti-inflammatoires</li></ul><p><strong>Traitement instrumental <span class=\"q\">— maladie interne, hors <span class=\"kw-clinique\">poussée</span></span></strong></p><p>Appliqué sur la <span class=\"kw-imagerie\">muqueuse rectale au-dessus du tissu hémorroïdaire</span>, en dehors des poussées</p><ul><li><span class=\"kw-ttt\">Ligature élastique</span> : meilleur compromis bénéfice / risque — <span class=\"kw-ci\">CI sous anticoagulants ou double anti-agrégation</span></li><li><span class=\"kw-ttt\">Sclérose</span> (chimique) · <span class=\"kw-ttt\">photocoagulation infrarouge</span> · <span class=\"kw-ttt\">cryothérapie</span> (thermique)</li><li>Bénéfice dans ≥ <span class=\"kw-chiffre\">3/4 des cas</span> ; à <span class=\"kw-clinique\">répéter</span> (<span class=\"kw-chiffre\">2-4 fois</span>, environ tous <span class=\"kw-clinique\">les</span> mois)</li></ul><p><strong>Traitement chirurgical <span class=\"q\">— formes sévères / compliquées</span></strong></p><p>Réservé aux <span class=\"kw-clinique\">grades sévères</span> ou aux <span class=\"kw-alerte\">complications</span> ; prévenir et évaluer avant le geste la <span class=\"kw-alerte\">séquelle fonctionnelle (incontinence)</span></p><ul><li><span class=\"kw-ttt\">Hémorroïdectomie</span> : traitement de référence en efficacité, mais <span class=\"kw-clinique\">plus douloureuse</span></li><li><span class=\"kw-ttt\">Pexie / fixation</span> (mécanique ou thermique) : moins douloureuse mais <span class=\"kw-alerte\">récidive plus fréquente</span></li></ul>","suivi":"<p><strong>Thrombose externe :</strong> régression spontanée <span class=\"kw-clinique\">ad integrum</span> en <span class=\"kw-chiffre\">5-15 jours</span> ; possibles <span class=\"kw-clinique\">fistulisation</span> ou <span class=\"kw-clinique\">marisque</span> résiduelle (préjudice esthétique).</p><p><strong><span class=\"kw-def\">Pronostic</span> :</strong> <span class=\"kw-def\">bénin</span>, <span class=\"kw-alerte\">pas de risque embolique</span> ; <span class=\"kw-clinique\">récidives possibles</span>, y compris sur le même site.</p><p><strong>Traitement instrumental :</strong> efficacité décroissante → à <span class=\"kw-clinique\">répéter</span> ; surveiller <span class=\"kw-alerte\">saignement sur chute d'escarre</span> et <span class=\"kw-alerte\">infection</span>.</p><p><strong><span class=\"kw-def\">Réévaluation</span> spécialisée :</strong> devant une <span class=\"kw-clinique\">récidive</span> ou une <span class=\"kw-clinique\">forme compliquée</span> (anémie, thrombose récidivante) → discuter la <span class=\"kw-ttt\">chirurgie</span>.</p>"},"liensGlobaux":[{"href":"https://www.fmcgastro.org/texte-postu/postu-2021-paris/prise-en-charge-de-la-maladie-hemorroidaire-recommandations-europeennes/","label":"Prise en charge de la maladie hemorroidaire recommandations europeennes"},{"href":"https://fr.wikipedia.org/wiki/Rectum","label":"Wikipedia — Rectum"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Maladie hémorroïdaire interne symptomatique — Forme symptomatique confirmée (sinon abstention) — après élimination d'une cause organique de saignement","detail":"<h4>CAT — maladie hémorroïdaire interne symptomatique — Prise en charge progressive selon le <span class=\"kw-def\">grade</span> de Goligher et la réponse au traitement</h4>","branches":[{"to":"t-chir","label":"Indication chirurgicale d'emblée (grade IV irréductible, anémie ferriprive, prolapsus thrombosé hyperalgique, thromboses externes récidivantes)","color":"red"},{"to":"q-grade","label":"Pas d'indication chirurgicale directe","color":"green"}]},{"id":"t-chir","kind":"terminal","label":"Hémorroïdectomie (traitement de référence)","color":"red","detail":"<h4>Indications directes</h4><ul><li><span class=\"kw-clinique\">Grade IV</span> : prolapsus <span class=\"kw-clinique\">irréductible</span> (<span class=\"kw-alerte\">rupture</span> totale du l<span class=\"kw-chiffre\">iga</span>ment de Parks)</li><li><span class=\"kw-etio\">Anémie ferriprive</span> liée aux saignements</li><li>Prolapsus <span class=\"kw-clinique\">thrombosé et hyperalgique</span></li><li>Thromboses externes <span class=\"kw-clinique\">récidivantes</span>, <span class=\"kw-clinique\">marisques hypertrophiques</span>, pathologie proctologique associée</li></ul><h4>Geste</h4><ul><li><span class=\"kw-ttt\">Hémorroïdectomie</span> (résection) sous <span class=\"kw-ttt\">anesthésie générale, péridurale ou locorégionale</span> — référence en efficacité, mais <span class=\"kw-clinique\">plus douloureuse</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Prévenir et évaluer avant le geste la <span class=\"kw-alerte\">séquelle fonctionnelle (incontinence)</span>, rare</li></ul>"},{"id":"q-grade","kind":"decision","label":"RHD + traitement médical bien conduits ? — Mesures hygiéno-diététiques + traitement médical = 1re ligne quel que soit le grade","branches":[{"to":"t-rhd","label":"Non encore tentés / efficaces — 1re ligne","color":"green"},{"to":"q-grade2","label":"Oui — échec : escalade selon le grade de Goligher","color":"amber"}]},{"id":"t-rhd","kind":"terminal","label":"RHD + traitement médical","color":"green","detail":"<h4><span class=\"kw-ttt\">Règles hygiéno-diététiques</span></h4><ul><li>Lutte contre la <span class=\"kw-clinique\">constipation chronique</span> ++</li><li>Alimentation riche en <strong>fibres solubles</strong> (lin, chia, psyllium)</li><li><span class=\"kw-ttt\">Laxatifs doux</span> si <span class=\"kw-clinique\">constipation</span> : <span class=\"kw-ttt\">mucilage</span> ou <span class=\"kw-ttt\">macrogol</span></li></ul><h4>Traitement médical (cure courte)</h4><ul><li><span class=\"kw-ttt\">Antalgiques</span>, <span class=\"kw-ttt\">AINS</span></li><li><span class=\"kw-ttt\">Veinotonique</span> (diosmine), <span class=\"kw-ttt\">topiques locaux</span></li></ul><h4>À éviter</h4><ul><li><span class=\"kw-ci\">Régimes d'exclusion alimentaire</span> (inefficaces)</li></ul>"},{"id":"q-grade2","kind":"decision","label":"Grade de procidence (classification de Goligher) ? — I = non prolabé · II = réintègre spontanément · III = réintégration digitale / récidivant · IV = irréductible","branches":[{"to":"t-photo","label":"Grade I–II","color":"blue"},{"to":"t-ligature","label":"Grade II–III","color":"amber"},{"to":"t-pexie","label":"Grade III récidivant","color":"amber"}]},{"id":"t-photo","kind":"terminal","label":"Photocoagulation infrarouge / sclérose","color":"blue","detail":"<h4>Modalités</h4><ul><li><span class=\"kw-ttt\">Photocoagulation infrarouge</span>, <span class=\"kw-ttt\">coagulation bipolaire</span>, <span class=\"kw-ttt\">cryothérapie</span> (thermique)</li><li><span class=\"kw-ttt\">Sclérose</span> chimique : injection <span class=\"kw-chiffre\">2 cm au-dessus de la ligne pectinée</span></li></ul><h4>Conditions</h4><ul><li>Sur la <span class=\"kw-imagerie\">muqueuse rectale au-dessus du tissu hémorroïdaire</span>, en dehors des poussées ; à <span class=\"kw-clinique\">répéter</span> (<span class=\"kw-chiffre\">2-4 fois</span>)</li></ul><h4>Complications</h4><ul><li><span class=\"kw-alerte\">Saignement sur chute d'escarre</span>, <span class=\"kw-alerte\">infection</span> (surtout après <span class=\"kw-ttt\">sclérose</span>)</li></ul>"},{"id":"t-ligature","kind":"terminal","label":"Ligature élastique","color":"amber","detail":"<h4>Modalité</h4><ul><li><span class=\"kw-ttt\">Ligature élastique</span> du paquet hémorroïdaire interne — <strong>meilleur compromis bénéfice / risque</strong></li></ul><h4><span class=\"kw-ci\">Contre-indication</span></h4><ul><li><span class=\"kw-ci\">Anticoagulants</span> ou <span class=\"kw-ci\">double anti-agrégation</span></li></ul><h4>Complications</h4><ul><li><span class=\"kw-alerte\">Saignement sur chute d'escarre</span> (surtout après l<span class=\"kw-chiffre\">iga</span>ture)</li></ul>"},{"id":"t-pexie","kind":"terminal","label":"Mucopexie / hémorroïdopexie","color":"amber","detail":"<h4>Modalité</h4><ul><li><span class=\"kw-ttt\">Ligature sous Doppler ± mucopexie</span> ou <span class=\"kw-ttt\">hémorroïdopexie</span> ; fixation mécanique ou thermique (radiofréquence, <span class=\"kw-ttt\">laser</span>)</li></ul><h4>Avantages / limite</h4><ul><li>Plus rapide, <span class=\"kw-clinique\">moins douloureuse</span>, immobilisation plus courte — mais <span class=\"kw-alerte\">risque de récidive plus important</span> qu'avec l'hémorroïdectomie</li></ul><h4>Escalade</h4><ul><li>En cas de nouvel échec → <span class=\"kw-ttt\">hémorroïdectomie</span></li></ul>"}]},"cards":[{"i":"1456bcdb242d","n":288,"o":"288-1","u":"Définition","t":"Connaître la définition des hémorroïdes","q":"Quels sont les deux groupes hémorroïdaires et leur localisation respective ?","a":"<div class=\"notion-course\"><ul><li>Le <strong>plexus interne</strong> : il est <strong>sus-pectinéal</strong> et intra-canalaire.</li><li>Le <strong>plexus externe</strong> : il est <strong>sous-pectinéal</strong> et se situe au niveau de la marge anale.</li></ul></div>"},{"i":"42a22efd7855","n":288,"o":"288-1","u":"Définition","t":"Connaître la définition des hémorroïdes","q":"Quelle est la composition anatomique d'une hémorroïde ?","a":"<div class=\"notion-course\"><ul><li>Des <strong><span class=\"nc-pink nc-bold\">lacs veineux</span></strong>.</li><li>De <strong><span class=\"nc-pink nc-bold\">petites artérioles sous-muqueuses</span></strong>.</li><li>Un <strong>réseau anastomotique intense</strong>, formant un véritable <span class=\"nc-pink nc-bold\">shunt artério-veineux</span>.</li><li>Un <strong><span class=\"nc-blue_bg nc-bold\">tissu de soutien</span></strong> composé de fibres musculaires lisses et de tissu collagène, qui ancre la structure.</li></ul></div>"},{"i":"99e067b19c9e","n":288,"o":"288-1","u":"Définition","t":"Connaître la définition des hémorroïdes","q":"Quel facteur physiologique peut conduire à l'apparition d'une maladie hémorroïdaire ?","a":"<div class=\"notion-course\"><p>La <strong>laxité du matériel d'ancrage</strong> des hémorroïdes, souvent liée au <span class=\"nc-orange_bg nc-bold\">vieillissement</span>, peut entraîner une <strong><span class=\"nc-red nc-bold\">procidence</span> ou une saillie</strong> des hémorroïdes, marquant le début de la maladie hémorroïdaire.</p></div>"},{"i":"bbc39df3d536","n":288,"o":"288-1","u":"Définition","t":"Connaître la définition des hémorroïdes","q":"Quelle est la définition des hémorroïdes (structures anatomiques) ?","a":"<div class=\"notion-course\"><p>Les hémorroïdes sont des <strong>structures anatomiques vasculaires</strong>, normalement présentes chez tout individu sain au niveau de l'anus. Elles sont physiologiques et ne constituent pas une maladie en soi.</p></div>"},{"i":"8b4d86829c03","n":288,"o":"288-10","u":"Contenu multimédia","t":"Photographies d’hémorroïdes externes et hémorroïdes internes prolabées","q":"Comment se présentent cliniquement les hémorroïdes internes prolabées ?","a":"<div class=\"notion-course\"><p>Les hémorroïdes internes prolabées sont des tuméfactions, qui peuvent être uniques ou multiples, de <strong>couleur rosée ou violacée</strong> (en cas de thrombose ou de strangulation), siégeant dans le <strong>canal anal</strong> et faisant saillie à l'extérieur de l'anus <strong>lors des <span class=\"nc-blue_bg\">efforts de poussée</span></strong>, voire de manière permanente selon le stade de la maladie.</p></div>"},{"i":"dda14617bb3b","n":288,"o":"288-10","u":"Contenu multimédia","t":"Photographies d’hémorroïdes externes et hémorroïdes internes prolabées","q":"Comment se présentent cliniquement les hémorroïdes externes à l'inspection ?","a":"<div class=\"notion-course\"><ul><li>Structures sous-cutanées de la marge anale, sous la <span class=\"nc-yellow_bg\">ligne pectinée</span>. Une tuméfaction <span class=\"nc-yellow_bg\">bleutée</span>, tendue et douloureuse évoque une thrombose externe ; cet aspect n’est pas celui de toute hémorroïde externe.</li></ul></div>"},{"i":"2cda12748a91","n":288,"o":"288-11","u":"Contenu multimédia","t":"Photographies de thrombose hémorroïdaire","q":"Quelle est la caractéristique sémiologique principale d'une thrombose hémorroïdaire externe, visible à l'inspection ?","a":"<div class=\"notion-course\"><ul><li>La photographie illustre une thrombose hémorroïdaire : tuméfaction <span class=\"nc-yellow_bg\">bleutée</span> douloureuse de la marge anale, parfois entourée d’œdème.</li></ul></div>"},{"i":"1303f0cc6359","n":288,"o":"288-13","u":"Prise en charge","t":"Connaître les grands principes de la prise en charge médicamenteuse et non médicamenteuse","q":"Quand et comment sont réalisés les traitements instrumentaux pour la pathologie hémorroïdaire interne, et quelle est leur caractéristique commune ?","a":"<div class=\"notion-course\"><p>Les traitements instrumentaux sont le traitement de fond de la maladie hémorroïdaire interne. Ils sont réalisés en consultation spécialisée, <span class=\"nc-green_bg\">à travers un anuscope</span>, et <strong>en dehors des poussées</strong>. Ils sont appliqués sur la muqueuse rectale au-dessus du tissu hémorroïdaire (pas sur les hémorroïdes elles-mêmes) car la muqueuse rectale est <strong>dépourvue de sensibilité thermo-algésique</strong>. Leur bénéfice est important dans plus de 3/4 des cas, mais l'efficacité est <strong>décroissante avec le suivi</strong>, nécessitant des répétitions (2 à 4 fois en moyenne, tous les mois).</p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Adapter le traitement aux symptômes, au prolapsus et aux préférences. Un grade IV ne rend pas obligatoire une chirurgie immédiate chez un patient asymptomatique ou à risque ; avis spécialisé. <span class=\"nc-pink_bg\">AINS</span> selon contre-indications, notamment grossesse, risque rénal et hémorragique.</li></ul></div></div>"},{"i":"27487fc98235","n":288,"o":"288-13","u":"Prise en charge","t":"Connaître les grands principes de la prise en charge médicamenteuse et non médicamenteuse","q":"Quelle est la pierre angulaire de la prise en charge non médicamenteuse de la pathologie hémorroïdaire et quel est son objectif principal ?","a":"<div class=\"notion-course\"><p>La pierre angulaire est la lutte contre la <strong>constipation chronique</strong>. Son objectif principal est de <ul><li>limiter l'installation de la maladie</li><li>résoudre les symptômes</li><li>prévenir les récidives et les complications</li></ul> pour la pathologie hémorroïdaire.</p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Adapter le traitement aux symptômes, au prolapsus et aux préférences. Un grade IV ne rend pas obligatoire une chirurgie immédiate chez un patient asymptomatique ou à risque ; avis spécialisé. <span class=\"nc-pink_bg\">AINS</span> selon contre-indications, notamment grossesse, risque rénal et hémorragique.</li></ul></div></div>"},{"i":"5be386e10f0c","n":288,"o":"288-13","u":"Prise en charge","t":"Connaître les grands principes de la prise en charge médicamenteuse et non médicamenteuse","q":"Quelles sont les options de traitement chirurgical de la pathologie hémorroïdaire et leurs principales différences ?","a":"<div class=\"notion-course\"><p>Les options de traitement chirurgical, réalisés sous anesthésie générale, péridurale ou locorégionale, sont :<ul><li>L'<strong><span class=\"nc-pink_bg\">hémorroïdectomie</span></strong> (résection) : c'est le traitement de référence en termes d'efficacité, mais plus douloureux.</li><li>Les techniques de <strong>fixation / pexie</strong> (mécanique ou thermique comme la radiofréquence, le laser) : elles sont plus rapides, <span class=\"nc-green nc-bold\">moins</span> douloureuses, avec une immobilisation plus courte, mais comportent un <strong><span class=\"nc-red nc-bold\">risque de récidive plus important</span></strong>.</li></ul></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Adapter le traitement aux symptômes, au prolapsus et aux préférences. Un grade IV ne rend pas obligatoire une chirurgie immédiate chez un patient asymptomatique ou à risque ; avis spécialisé. <span class=\"nc-pink_bg\">AINS</span> selon contre-indications, notamment grossesse, risque rénal et hémorragique.</li></ul></div></div>"},{"i":"67e5d73d0204","n":288,"o":"288-13","u":"Prise en charge","t":"Connaître les grands principes de la prise en charge médicamenteuse et non médicamenteuse","q":"Quelles sont les principales techniques de traitement instrumental pour la pathologie hémorroïdaire et leurs particularités ?","a":"<div class=\"notion-course\"><p>Les principales techniques de traitement instrumental sont :<ul><li>La <strong><span class=\"nc-blue_bg\">ligature élastique</span></strong> (technique ischémique) : considérée comme le meilleur compromis bénéfice/risque, mais <strong>contre-indiquée sous anticoagulants ou double anti-agrégation</strong>.</li><li>La <strong>sclérose</strong> (technique chimique) : injection d'un produit sclérosant 2 cm au-dessus de la <span class=\"nc-yellow_bg\">ligne pectinée</span>.</li><li>La <strong>photocoagulation infrarouge</strong> (technique thermique).</li><li>La <strong>coagulation bipolaire</strong> (technique thermique).</li><li>La <strong>cryothérapie</strong> (technique thermique).</li></ul></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Adapter le traitement aux symptômes, au prolapsus et aux préférences. Un grade IV ne rend pas obligatoire une chirurgie immédiate chez un patient asymptomatique ou à risque ; avis spécialisé. <span class=\"nc-pink_bg\">AINS</span> selon contre-indications, notamment grossesse, risque rénal et hémorragique.</li></ul></div></div>"},{"i":"9cdc972c12d6","n":288,"o":"288-13","u":"Prise en charge","t":"Connaître les grands principes de la prise en charge médicamenteuse et non médicamenteuse","q":"Comment le traitement de la pathologie hémorroïdaire est-il adapté selon le grade de Goligher ?","a":"<div class=\"notion-course\"><p>Le traitement est <strong>progressif</strong> et adapté au grade de sévérité selon l'escalade thérapeutique. On n'escalade qu'en cas d'échec du palier précédent :<ul><li><strong>Grade I</strong> : Règles Hygiéno-Diététiques (RHD) + traitement médical. Si échec : photocoagulation infrarouge ou <span class=\"nc-blue_bg\">sclérose</span>, puis ligature.</li><li><strong>Grade II</strong> : RHD + traitement médical. Si échec : photocoagulation, <span class=\"nc-blue_bg\">sclérose</span> ou <span class=\"nc-blue_bg\">ligature élastique</span>, puis hémorroïdopexie / <span class=\"nc-blue_bg\">hémorroïdectomie</span>.</li><li><strong>Grade III</strong> : RHD + traitement médical. Si échec : <span class=\"nc-blue_bg\">ligature élastique</span>, puis mucopexie / hémorroïdopexie, voire <span class=\"nc-blue_bg\">hémorroïdectomie</span>.</li><li>Avis chirurgical pour prolapsus irréductible symptomatique ; choix du traitement selon gêne, terrain, traitements antérieurs et préférences. La chirurgie n’est pas une obligation immédiate pour tout grade IV.</li></ul>Le principe général est de débuter par les RHD et le traitement médical, puis les procédés mini-invasifs avant d'envisager la chirurgie pour les formes sévères ou compliquées.</p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Adapter le traitement aux symptômes, au prolapsus et aux préférences. Un grade IV ne rend pas obligatoire une chirurgie immédiate chez un patient asymptomatique ou à risque ; avis spécialisé. <span class=\"nc-pink_bg\">AINS</span> selon contre-indications, notamment grossesse, risque rénal et hémorragique.</li></ul></div></div>"},{"i":"f287afc987da","n":288,"o":"288-13","u":"Prise en charge","t":"Connaître les grands principes de la prise en charge médicamenteuse et non médicamenteuse","q":"Quels sont les grands principes du traitement médicamenteux des hémorroïdes et quels types de médicaments sont utilisés ?","a":"<div class=\"notion-course\"><p>Le traitement médicamenteux vise une utilisation <strong>ponctuelle</strong> lors des épisodes douloureux, en cure courte, et n'est pas le traitement des formes chroniques. Les médicaments utilisés incluent :<ul><li><strong>Antalgiques et AINS</strong> (Anti-Inflammatoires Non Stéroïdiens)</li><li><strong>Veinotoniques</strong> (ex: <strong>diosmine</strong>) dont l'efficacité est démontrée pour diminuer l'intensité et la durée des symptômes</li><li><strong><span class=\"nc-pink_bg\">Topiques locaux</span></strong> (<span class=\"nc-green nc-bold\">émollients</span>, analgésiques, anti-inflammatoires, anti-œdème, favorisant la cicatrisation)</li></ul></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Adapter le traitement aux symptômes, au prolapsus et aux préférences. Un grade IV ne rend pas obligatoire une chirurgie immédiate chez un patient asymptomatique ou à risque ; avis spécialisé. <span class=\"nc-pink_bg\">AINS</span> selon contre-indications, notamment grossesse, risque rénal et hémorragique.</li></ul></div></div>"},{"i":"02d1793e38fe","n":288,"o":"288-14","u":"Prise en charge","t":"Connaître les quatre règles de préambule thérapeutique","q":"Quelle est la troisième règle de préambule thérapeutique concernant l'utilisation des traitements médicamenteux pour la pathologie hémorroïdaire ?","a":"<div class=\"notion-course\"><p>Les traitements médicamenteux sont habituellement <span class=\"nc-red nc-bold\">réservés aux </span><strong><span class=\"nc-red nc-bold\">symptômes aigus</span></strong><span class=\"nc-red nc-bold\"> et proposés en </span><strong><span class=\"nc-red nc-bold\">cure courte</span></strong>.</p></div>"},{"i":"06d247edc0cf","n":288,"o":"288-14","u":"Prise en charge","t":"Connaître les quatre règles de préambule thérapeutique","q":"Quelle est la deuxième règle de préambule thérapeutique concernant la justification du traitement de la pathologie hémorroïdaire ?","a":"<div class=\"notion-course\"><p>Dans la majorité des cas, le traitement de la pathologie hémorroïdaire est un <strong>traitement de confort</strong>.</p></div>"},{"i":"954d0213b3c5","n":288,"o":"288-14","u":"Prise en charge","t":"Connaître les quatre règles de préambule thérapeutique","q":"Quelle est la première règle de préambule thérapeutique concernant la prise en charge de la pathologie hémorroïdaire ?","a":"<div class=\"notion-course\"><p>Le <span class=\"nc-yellow_bg\">traitement des hémorroïdes doit être réservé aux </span><strong><span class=\"nc-yellow_bg\">formes symptomatiques</span></strong>.</p></div>"},{"i":"9b83ca3c6137","n":288,"o":"288-14","u":"Prise en charge","t":"Connaître les quatre règles de préambule thérapeutique","q":"Quelle est la quatrième règle de préambule thérapeutique concernant le type de traitement et la prise en charge des hémorroïdes ?","a":"<div class=\"notion-course\"><p>Les procédés instrumentaux et chirurgicaux constituent le <span class=\"nc-red nc-bold\">traitement de la maladie hémorroïdaire </span><strong><span class=\"nc-red nc-bold\">interne</span></strong> et relèvent d'une <strong>prise en charge spécialisée</strong>.</p></div>"},{"i":"2c0165ac7e22","n":288,"o":"288-15","u":"Prise en charge","t":"Connaître le traitement de la thrombose hémorroïdaire externe","q":"Quelle est la principale contre-indication au geste local (excision/incision) pour une thrombose hémorroïdaire externe ?","a":"<div class=\"notion-course\"><p>La principale contre-indication est une <strong>thrombose œdémateuse</strong>, en raison d'un risque d'inefficacité et d'<span class=\"nc-red nc-bold\">hémorragie</span>.</p></div>"},{"i":"734e5191f435","n":288,"o":"288-15","u":"Prise en charge","t":"Connaître le traitement de la thrombose hémorroïdaire externe","q":"Quels sont les traitements médicaux recommandés pour la thrombose hémorroïdaire externe ?","a":"<div class=\"notion-course\"><ul><li><strong>AINS</strong> (anti-inflammatoires non stéroïdiens) en première intention.</li><li><strong>Antalgiques de palier 1-2</strong>.</li><li><strong>Topiques</strong> contenant un anesthésique local.</li><li>Veinotoniques (niveau de preuve faible).</li><li><strong>Corticoïdes</strong> en cure courte : alternative si contre-indication aux AINS et au traitement chirurgical, surtout en cas de forte composante œdémateuse.</li></ul></div>"},{"i":"a0a2c5b9a1ea","n":288,"o":"288-15","u":"Prise en charge","t":"Connaître le traitement de la thrombose hémorroïdaire externe","q":"Quel est le principe général du traitement de la thrombose hémorroïdaire externe, en particulier pour la gestion de la douleur ?","a":"<div class=\"notion-course\"><p>Le traitement de la thrombose hémorroïdaire externe est avant tout une <strong>urgence <span class=\"nc-pink_bg\">antalgique</span></strong>.</p></div>"},{"i":"c21f006ab135","n":288,"o":"288-15","u":"Prise en charge","t":"Connaître le traitement de la thrombose hémorroïdaire externe","q":"Quel geste local peut être proposé en cas de thrombose hémorroïdaire externe, et quelles sont ses indications ?","a":"<div class=\"notion-course\"><p>Un geste local, tel que l'<strong>excision</strong> ou l'incision de la zone thrombosée, peut être réalisé en consultation. L'excision est préférable pour son efficacité et sa durabilité.</p><p>Les indications sont :</p><ul><li><span class=\"nc-pink nc-bold\">D'emblée si la thrombose est vue </span><strong><span class=\"nc-pink nc-bold\">précocement</span></strong>.</li><li>En cas d'<strong>inefficacité du traitement médical après 24-48 heures</strong>.</li></ul></div>"},{"i":"194a5e6f769f","n":288,"o":"288-4","u":"Diagnostic positif","t":"Savoir distinguer les hémorroïdes externes et internes","q":"Comment différencier la visibilité et la palpabilité des hémorroïdes externes et internes en l'absence de complication ?","a":"<div class=\"notion-course\"><p>Les hémorroïdes externes ne sont normalement <strong>pas visibles</strong> et sont <strong>non palpables</strong>, sauf en cas de thrombose. Les hémorroïdes internes ne sont visibles qu'en <strong>anuscopie</strong> (sauf <span class=\"nc-red nc-bold\">prolapsus</span> extériorisé) et sont <strong>non palpables</strong>.</p></div>"},{"i":"64f9d659cb32","n":288,"o":"288-4","u":"Diagnostic positif","t":"Savoir distinguer les hémorroïdes externes et internes","q":"Comment distinguer la localisation des hémorroïdes externes et internes par rapport à la ligne pectinée ?","a":"<div class=\"notion-course\"><p>Les hémorroïdes externes sont localisées en région <strong>péri-anale</strong>, immédiatement sous-cutanée, dans les <span class=\"nc-purple nc-bold\">plis radiés de l'anus</span>. Les hémorroïdes internes sont <strong>intra-canalaires</strong>, en sus-pectinéal.</p></div>"},{"i":"c756c74a05dd","n":288,"o":"288-4","u":"Diagnostic positif","t":"Savoir distinguer les hémorroïdes externes et internes","q":"Quelles sont les complications des hémorroïdes externes et internes ?","a":"<div class=\"notion-course\"><ul><li>La <span class=\"nc-red nc-bold\">seule complication des hémorroïdes externes</span> est la <strong><span class=\"nc-red nc-bold\">thrombose hémorroïdaire externe</span></strong>.</li><li>Les hémorroïdes internes peuvent se compliquer d'<strong><span class=\"nc-red nc-bold\">hémorragie</span></strong>, de <strong><span class=\"nc-red nc-bold\">prolapsus</span>/<span class=\"nc-red nc-bold\">procidence</span></strong>, de <strong><span class=\"nc-red nc-bold\">crise hémorroïdaire</span></strong> (fluxionnaire) ou, plus rarement, de <strong><span class=\"nc-red nc-bold\">thrombose hémorroïdaire interne</span></strong>.</li></ul></div>"},{"i":"d562c35842cd","n":288,"o":"288-4","u":"Diagnostic positif","t":"Savoir distinguer les hémorroïdes externes et internes","q":"Quelles sont les différences de revêtement histologique entre les hémorroïdes externes et internes ?","a":"<div class=\"notion-course\"><p>Le plexus externe est recouvert d'un <span class=\"nc-purple nc-bold\">épithélium de type </span><strong><span class=\"nc-purple nc-bold\">malpighien</span></strong>. Le plexus interne est recouvert d'un <span class=\"nc-purple nc-bold\">épithélium de type </span><strong><span class=\"nc-purple nc-bold\">intestinal</span></strong>.</p></div>"},{"i":"000da664dfdb","n":288,"o":"288-5","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une thrombose hémorroïdaire","q":"Quels sont les autres symptômes pouvant accompagner une thrombose hémorroïdaire externe ?","a":"<div class=\"notion-course\"><ul><li>Perception d'une <strong>boule à l'anus</strong>.</li><li><strong><span class=\"nc-blue_bg\">Saignements tardifs et inconstants</span></strong>, notamment en cas de fistulisation spontanée, qui s'accompagne alors d'une diminution de la douleur.</li></ul></div>"},{"i":"07d72a8e9a26","n":288,"o":"288-5","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une thrombose hémorroïdaire","q":"Quelles sont les spécificités du diagnostic de la thrombose hémorroïdaire interne, par rapport à l'externe ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-red nc-bold\">thrombose hémorroïdaire interne</span> est <strong>beaucoup plus rare</strong>. Elle se manifeste par une <strong><span class=\"nc-blue_bg\">douleur anale aiguë perçue comme « interne »</span></strong>, avec une <span class=\"nc-green_bg\">marge anale normale</span>. Le <strong>toucher rectal est très <span class=\"nc-green nc-bold\">douloureux</span></strong> et perçoit le thrombus alors que l'<strong><span class=\"nc-yellow_bg\">anuscopie permet de confirmer le diagnostic</span></strong>.</p></div>"},{"i":"550b85f115e8","n":288,"o":"288-5","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une thrombose hémorroïdaire","q":"Quelle est la particularité de l'examen clinique et des examens complémentaires pour le diagnostic d'une thrombose hémorroïdaire externe ?","a":"<div class=\"notion-course\"><p>Le diagnostic est <strong>clinique</strong> et repose sur l'examen de la zone anale qui révèle une <strong><span class=\"nc-yellow_bg\">tuméfaction ferme mais non dure</span>, <span class=\"nc-yellow_bg\">bleutée</span> et <span class=\"nc-yellow_bg\">douloureuse à la palpation</span></strong>. Une <strong>réaction œdémateuse</strong> est souvent associée et peut masquer le thrombus. Le <strong>toucher rectal et l'anuscopie doivent être évités</strong> car très <span class=\"nc-green nc-bold\">douloureux</span>, sauf en cas de doute diagnostique. Les <strong>examens complémentaires ne sont pas nécessaires</strong>.</p></div>"},{"i":"8dade85109a7","n":288,"o":"288-5","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une thrombose hémorroïdaire","q":"Quelle est la définition et la localisation typique d'une thrombose hémorroïdaire externe, la seule complication des hémorroïdes externes ?","a":"<div class=\"notion-course\"><p>La <span class=\"nc-red nc-bold\">thrombose hémorroïdaire externe</span> se manifeste par une <strong>tuméfaction ferme, <span class=\"nc-yellow_bg\">bleutée</span> et douloureuse</strong>, siégeant dans les <strong><span class=\"nc-purple nc-bold\">plis radiés de l'anus</span></strong>. C'est la <span class=\"nc-red nc-bold\">seule complication des hémorroïdes externes</span>.</p></div>"},{"i":"933042dc870a","n":288,"o":"288-5","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une thrombose hémorroïdaire","q":"Comment caractériser la douleur associée à une thrombose hémorroïdaire externe aiguë ?","a":"<div class=\"notion-course\"><p>La douleur est <strong>anale aiguë</strong>, d'installation <strong><span class=\"nc-red nc-bold\">brutale</span></strong> et d'<strong>intensité intense</strong>. Elle associe une <span class=\"nc-red nc-bold\">sensation de </span><strong><span class=\"nc-red nc-bold\">cuisson</span>, de <span class=\"nc-red nc-bold\">tension</span> et une <span class=\"nc-red nc-bold\">douleur vive</span></strong>. Contrairement à la <span class=\"nc-orange_bg\">fissure anale</span>, elle est <strong><span class=\"nc-green nc-bold\">peu ou pas rythmée par la défécation</span></strong> et contrairement aux suppurations, elle est <strong><span class=\"nc-green nc-bold\">rarement insomniante</span></strong>.</p></div>"},{"i":"99a3454ccef5","n":288,"o":"288-5","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’une thrombose hémorroïdaire","q":"Quels sont les principaux facteurs déclenchants d'une thrombose hémorroïdaire externe selon le contexte clinique ?","a":"<div class=\"notion-course\"><ul><li><strong>Exercice physique</strong>, et notamment le cyclisme.</li><li><span class=\"nc-brown_bg\">Contrainte mécanique</span> locale.</li><li><strong><span class=\"nc-brown_bg\">Traumatisme</span></strong>, notamment l'<strong>accouchement</strong>.</li></ul></div>"},{"i":"6443e74b17ec","n":288,"o":"288-6","u":"Diagnostic positif","t":"Connaître les manifestations cliniques les plus fréquentes des hémorroïdes internes","q":"Décrivez les caractéristiques d'une hémorragie liée aux hémorroïdes internes.","a":"<div class=\"notion-course\"><p>L'<span class=\"nc-red nc-bold\">hémorragie</span> hémorroïdaire se manifeste par :</p><ul><li>Un horaire contemporain de la <strong>défécation</strong> ou immédiatement après.</li><li>Un sang de couleur <strong>rouge rutilant</strong> et <span class=\"nc-blue_bg\">vif</span> (d'origine artériolaire), généralement <span class=\"nc-yellow_bg\">non mélangé aux selles</span>.</li><li>Une <span class=\"nc-brown_bg\">abondance souvent </span><strong><span class=\"nc-brown_bg\">faible</span></strong>, se présentant comme un goutte-à-goutte (rarement giclant), souvent surestimée par les patients.</li></ul></div>"},{"i":"8f2142976285","n":288,"o":"288-6","u":"Diagnostic positif","t":"Connaître les manifestations cliniques les plus fréquentes des hémorroïdes internes","q":"Quelles sont les trois principales manifestations cliniques des hémorroïdes internes ?","a":"<div class=\"notion-course\"><p>Les trois principales manifestations cliniques des hémorroïdes internes sont :</p><ul><li>Les <strong>hémorragies</strong>.</li><li>Le <strong><span class=\"nc-red nc-bold\">prolapsus</span></strong> ou la <strong><span class=\"nc-red nc-bold\">procidence</span></strong>.</li><li>Les <strong>douleurs</strong> (lors d'une crise fluxionnaire).</li></ul></div>"},{"i":"b39de9081049","n":288,"o":"288-6","u":"Diagnostic positif","t":"Connaître les manifestations cliniques les plus fréquentes des hémorroïdes internes","q":"Quelle est la caractéristique principale du grade 2 de la classification de Goligher pour le prolapsus hémorroïdaire ?","a":"<div class=\"notion-course\"><p>Dans le grade 2 de la classification de Goligher, les hémorroïdes internes sont <strong>prolabées</strong> (visiblement en <span class=\"nc-blue_bg\">procidence dans la lumière de l'anuscope</span>) et <strong>se réintègrent spontanément</strong> dans le canal anal.</p></div>"},{"i":"d3a3f52eae17","n":288,"o":"288-6","u":"Diagnostic positif","t":"Connaître les manifestations cliniques les plus fréquentes des hémorroïdes internes","q":"En ce qui concerne le prolapsus hémorroïdaire, expliquez son mécanisme et les signes associés à sa présence.","a":"<div class=\"notion-course\"><p>Le <span class=\"nc-red nc-bold\">prolapsus</span> résulte d'une <strong><span class=\"nc-blue_bg\">laxité du tissu conjonctif sous-muqueux</span></strong><span class=\"nc-blue_bg\"> des hémorroïdes internes</span>, ce qui entraîne leur extériorisation par l'orifice anal, notamment <span class=\"nc-red nc-bold\">lors de la défécation</span>, voire <span class=\"nc-red nc-bold\">en permanence</span>.</p><p>Les signes associés sont :</p><ul><li>Une <strong><span class=\"nc-blue_bg\">gêne mécanique</span></strong>, décrite comme une sensation de « boule sortante » lors des <span class=\"nc-blue_bg\">efforts de poussée</span>.</li><li>Dans les formes fréquentes ou permanentes (grades 3-4), on peut observer du <strong><span class=\"nc-blue_bg\">prurit</span></strong>, un <strong><span class=\"nc-blue_bg\">suintement</span></strong> et des <strong><span class=\"nc-blue_bg\">brûlures anales</span></strong> (bien que le <span class=\"nc-blue_bg\">prurit</span> ne soit pas une indication de traitement instrumental ou chirurgical des hémorroïdes).</li></ul></div>"},{"i":"e6b387cd6e55","n":288,"o":"288-6","u":"Diagnostic positif","t":"Connaître les manifestations cliniques les plus fréquentes des hémorroïdes internes","q":"Qu'est-ce qui caractérise le grade 4 de la classification de Goligher du prolapsus hémorroïdaire interne ?","a":"<div class=\"notion-course\"><p>Le grade 4 de la classification de Goligher correspond à des hémorroïdes internes <strong>prolabées et visibles <span class=\"nc-red nc-bold\">en permanence</span></strong> à l'extérieur de l'anus, même sans anuscope. Elles sont <strong><span class=\"nc-red nc-bold\">non réintégrables</span></strong>, signant une <span class=\"nc-red nc-bold\">rupture totale du ligament de Parks</span>.</p></div>"},{"i":"63149223505e","n":288,"o":"288-2","u":"Epidémiologie","t":"Connaître la fréquence de la pathologie hémorroïdaire","q":"Quels sont les points essentiels concernant la fréquence de la pathologie hémorroïdaire ?","a":"<div class=\"notion-course\"><p>La pathologie hémorroïdaire est l'<span>affection la plus fréquente en proctologie</span>.</p>\n\n      <h5>Fréquence</h5>\n      <ul>\n        <li>Environ <span>1/3 de la population</span> a eu au moins un symptôme hémorroïdaire au cours de l'année écoulée (et <span>1/3 d'entre eux</span> consultent).</li>\n        <li>Jusqu'à <span>80 % de la population générale</span> serait concernée au moins une fois dans sa vie.</li>\n      </ul>\n\n      <h5><span>Terrain</span></h5>\n      <ul>\n        <li>Peut s'observer à <span>tout âge</span>.</li>\n        <li><span>Sans prédisposition féminine ni masculine</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">⚠️ <strong>Maladie bénigne, mais vigilance carcinologique.</strong> La <span>maladie hémorroïdaire</span> <span class=\"nc-green_bg\">ne </span><span><span class=\"nc-green_bg\">menace</span></span><span class=\"nc-green_bg\"> pas le </span><span><span class=\"nc-green_bg\">pronostic vital</span></span> et <span><span class=\"nc-green_bg\">ne dégénère pas</span></span>. En revanche, <span>les</span> <span>saignements hémorroïdaires</span> peuvent <span>gêner le dépistage du cancer colorectal</span> : un <span>saignement survenant à l'occasion d'une défécation</span> est un <span>signe d'alarme</span> qui impose une <span><span class=\"nc-blue nc-bold\">exploration colorectale</span></span> (attitude à nuancer selon le <span>terrain</span> et le contexte). Discriminant : le <span class=\"nc-yellow_bg\">saignement hémorroïdaire survient classiquement </span><span><span class=\"nc-yellow_bg\">à la fin de la selle</span>, <span class=\"nc-yellow_bg\">non mélangé aux selles</span></span>.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 301 — Tumeur colon - rectum</em></p></div>"},{"i":"2dde15d58396","n":288,"o":"288-3","u":"Physiopathologie","t":"Connaître la physiopathologie des hémorroïdes","q":"Quels sont les points essentiels concernant la physiopathologie des hémorroïdes ?","a":"<div class=\"notion-course\"><p>La <span>maladie hémorroïdaire</span> représente l'ensemble des plaintes en lien avec <span>les</span> <span>modifications du tissu hémorroïdaire</span>. On distingue :</p>\n      <ul>\n        <li><span><span class=\"nc-orange_bg\">Crise</span></span> : plaintes de <span>courte durée comportant une composante douloureuse</span>.</li>\n        <li><span><span class=\"nc-orange_bg\">Maladie chronique</span></span> : <span>signes réguliers</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">⚠️ <strong><span class=\"nc-brown_bg\">Pas de corrélation anatomo-clinique</span></strong> : de petites hémorroïdes peuvent être symptomatiques et de grosses hémorroïdes asymptomatiques (même si <span>les</span> symptômes s'accompagnent habituellement d'une modification morphologique).</div>\n\n      <h5><span>Les</span> deux théories physiopathologiques</h5>\n      <table>\n        <thead>\n          <tr><th>Théorie</th><th>Principe et conséquences</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span>Théorie mécanique</span></td>\n            <td>\n              <strong>Mécanisme :</strong> <span>fragilisation du <span class=\"nc-blue_bg nc-bold\">tissu de soutien</span></span> / matériel d'ancrage des hémorroïdes internes.<br>\n              <strong><span>Facteurs de risque</span> évoqués :</strong> <span><span class=\"nc-blue_bg\">accouchement</span></span> ; <span><span class=\"nc-blue_bg\">long temps passé à la selle</span></span> ; <span><span class=\"nc-blue_bg\">efforts de poussée</span></span> (<span>dyschésie</span>) ; <span>selles dures</span>.<br>\n              <strong>Conséquence thérapeutique :</strong> la prise en charge vise à renforcer / repositionner le tissu hémorroïdaire (traitements instrumentaux, certains traitements chirurgicaux).\n            </td>\n          </tr>\n          <tr>\n            <td><span>Théorie vasculaire</span></td>\n            <td>\n              <strong>Principe :</strong> la maladie s'apparente à une <span>insuffisance veineuse</span> — argumentée par l'<span>augmentation de taille du tissu en fin de grossesse</span> et l'efficacité à court terme des <span>veinotoniques</span>.<br>\n              <strong>Limites :</strong> <span>les</span> <span>hémorroïdes ne sont pas des veines</span> (pas de valvules conniventes) ; les <span>saignements rouges de la <span class=\"nc-orange_bg\">crise</span> ne sont pas veineux</span>.\n            </td>\n          </tr>\n        </tbody>\n      </table></div>"},{"i":"e360bfa6fff7","n":288,"o":"288-7","u":"Diagnostic positif","t":"Connaître le diagnostic différentiel des hémorroïdes internes","q":"Quels sont les points essentiels concernant le diagnostic différentiel des hémorroïdes internes ?","a":"<div class=\"notion-course\"><p>Message clé : le <span>saignement hémorroïdaire est aspécifique</span>. <span>Aucun élément symptomatique</span> ne permet d'attribuer avec certitude un saignement à une origine hémorroïdaire.</p>\n\n      <h5>Quand évoquer un autre diagnostic</h5>\n      <ul>\n        <li><span><span class=\"nc-red_bg\">Saignements indépendants de la défécation</span></span> : possibles, mais doivent faire évoquer un autre diagnostic.</li>\n        <li><span>Saignements colorant les selles</span> : doivent également faire évoquer une autre cause — notamment un <span>cancer colorectal</span> ou une <span>MICI</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">🚩 Un <span>saignement survenant à l'occasion d'une défécation</span> est un signe d'alarme imposant une <span><span class=\"nc-blue nc-bold\">exploration colorectale</span></span> (attitude à nuancer selon le <span>terrain</span> et le contexte clinique). Devant des <span>rectorragies</span>, on ne se contente jamais d'attribuer le saignement aux hémorroïdes : il faut <span>éliminer une cause organique</span>.</div>\n\n      <p>⚠️ La fiche source reste volontairement succincte sur une liste exhaustive de diagnostics différentiels des hémorroïdes internes : le point retenu est le <span>caractère aspécifique du saignement</span> et la <span>nécessité d'éliminer une cause organique</span>.</p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 301 — Tumeur colon - rectum · 282 — <span>MICI</span></em></p></div>"},{"i":"d13d26245ae1","n":288,"o":"288-8","u":"Diagnostic positif","t":"Connaître le diagnostic différentiel de la thrombose hémorroïdaire externe","q":"Quels sont les points essentiels concernant le diagnostic différentiel de la thrombose hémorroïdaire externe ?","a":"<div class=\"notion-course\"><p>Le <span>diagnostic différentiel</span> de la thrombose hémorroïdaire externe regroupe <span>les</span> <strong>autres causes de douleur anale aiguë</strong>.</p>\n\n      \n      <table>\n        <thead>\n          <tr><th>Étiologie</th><th>Type de douleur</th><th>Rythme</th><th>Durée</th><th>Signes associés</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"nc-red nc-bold\">Crise hémorroïdaire</span></strong></td>\n            <td>Cuisson.</td>\n            <td>Per- et <span class=\"nc-yellow_bg\">post-défécatoire</span>, <strong><span class=\"nc-yellow_bg nc-bold\">peu durable</span></strong>.</td>\n            <td><span><span class=\"nc-pink nc-bold\">24-72 h</span></span>.</td>\n            <td><span>Œdème</span>, <span class=\"nc-red nc-bold\">procidence</span>, saignement.</td>\n          </tr>\n          <tr>\n            <td><strong>Thrombose hémorroïdaire</strong></td>\n            <td>Douleur intense « exquise ».</td>\n            <td><span class=\"nc-green_bg\">Non rythmée par la selle</span>.</td>\n            <td>Heures à jours.</td>\n            <td><span><span class=\"nc-blue_bg\">Tuméfaction</span></span><span class=\"nc-blue_bg\"> anale douloureuse bleutée bien limitée</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"nc-orange_bg\">Fissure anale</span></strong></td>\n            <td>Brûlure.</td>\n            <td>Per- et <span class=\"nc-yellow_bg\">post-défécatoire</span> <strong><span class=\"nc-yellow_bg nc-bold\">durable</span></strong> (persiste plusieurs heures).</td>\n            <td>Semaines.</td>\n            <td>Saignement.</td>\n          </tr>\n          <tr>\n            <td><strong><span>Abcès</span></strong></td>\n            <td><span class=\"nc-red nc-bold\">Tension</span>, douleur pongitive.</td>\n            <td>\n              <strong><span class=\"nc-red nc-bold\">Positionnel de </span><span><span class=\"nc-red nc-bold\">contact</span></span> :</strong> augmentée au toucher / appui ;<br>\n              <strong><span><span class=\"nc-red nc-bold\">Inflammatoire</span></span> :</strong> insomniante.\n            </td>\n            <td>Récente (quelques heures), <span class=\"nc-red nc-bold\">continue</span>.</td>\n            <td><span>Tuméfaction</span> périanale mal limitée, <span class=\"nc-blue_bg\">rouge mais non bleutée</span>, <span class=\"nc-blue_bg\">halo érythémateux</span>, <span><span class=\"nc-orange_bg\">dysurie</span></span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Fécalome / Cancer</strong></td>\n            <td>Épreintes.</td>\n            <td><span class=\"nc-yellow_bg\">Avant la selle</span> (<span class=\"nc-yellow_bg\">douleurs expulsives</span>).</td>\n            <td>Jours.</td>\n            <td><span class=\"nc-red_bg\">Suintements</span>, <span class=\"nc-red_bg\">incontinence</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Herpès</strong></td>\n            <td><span class=\"nc-brown_bg\">Brûlures intenses</span>.</td>\n            <td><span class=\"nc-red nc-bold\">Péri-anales en quadrant</span>.</td>\n            <td>Jours.</td>\n            <td><span class=\"nc-blue_bg\">Lésions ulcérées et érosives périanales</span>, <span><span class=\"nc-orange_bg\">dysurie</span></span>, <span class=\"nc-orange_bg\">hyperesthésie régionale</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Proctalgie fugace</strong></td>\n            <td>Crampe intense.</td>\n            <td>Début brutal, sans facteur déclenchant franc.</td>\n            <td>Minutes (parfois nocturne).</td>\n            <td>Aucun.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Focus — la <span class=\"nc-orange_bg\">fissure anale</span> (<span>diagnostic différentiel</span> principal)</h5>\n      <p>Le diagnostic est évoqué devant une <strong>triade</strong> :</p>\n      <ul>\n        <li><span>Ulcération épithéliale en forme de raquette</span> à la partie basse du canal anal, <strong>postérieure dans <span>75 %</span> des cas</strong> (plus rarement antérieure ou bipolaire).</li>\n        <li><span>Hypertonie du sphincter interne</span> (sphincter contracté au repos, responsable de la douleur).</li>\n        <li><span>Douleur typique en 3 temps</span> : déclenchée par le passage des selles → <span>rémission</span> transitoire de quelques secondes à minutes → reprise douloureuse plus ou moins prolongée (peut durer quelques heures).</li>\n      </ul>\n      <p>Devant une forme atypique (fissure indolore, latérale, absence de contracture sphinctérienne), il faut évoquer :</p>\n      <ul>\n        <li><span>Ulcération</span> de la <span>maladie de Crohn</span>.</li>\n        <li><span><span class=\"nc-orange_bg\">Carcinome épidermoïde</span> de l'anus</span> (plus rarement une hémopathie maligne).</li>\n        <li><span>Infection sexuellement transmissible</span> : <span>syphilis</span>, <span>VIH</span>, <span>tuberculose</span>, <span>chlamydiae</span>, <span>herpès simplex</span>.</li>\n        <li><span>Traumatisme</span> (valeur du contexte).</li>\n        <li><span>Séquelle de radiothérapie</span> (valeur du contexte).</li>\n        <li><span>Maladie de système</span> : <span>maladie de Behçet</span>, <span>granulomatose de Wegener</span>.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 282 — <span>MICI</span></em></p></div>"},{"i":"a150a2ecab65","n":288,"o":"288-9","u":"Diagnostic positif","t":"Connaître les autres manifestations possibles des hémorroïdes internes","q":"Quels sont les points essentiels concernant les autres manifestations possibles des hémorroïdes internes ?","a":"<div class=\"notion-course\"><h5><span class=\"nc-red nc-bold\">Anémie ferriprive par saignement chronique</span></h5>\n      <ul>\n        <li><span>Anémie ferriprive</span> liée à un saignement hémorroïdaire chronique : <span>très rare</span>.</li>\n        <li>Doit faire <span>éliminer les autres causes d'anémie ferriprive</span> avant de l'attribuer aux hémorroïdes.</li>\n      </ul>\n\n      <h5><span class=\"nc-orange_bg\">Crise</span> fluxionnaire (hémorroïdaire)</h5>\n      <ul>\n        <li>Regroupe <span>toutes les douleurs causées par une hémorroïde interne, <span class=\"nc-yellow_bg\">hors thrombose</span></span> — y compris <span><span class=\"nc-blue nc-bold\">sensation</span> de <span class=\"nc-blue nc-bold\">chaleur</span> et <span class=\"nc-blue nc-bold\">pesanteur</span> <span class=\"nc-blue nc-bold\">périnéale</span></span>.</li>\n        <li>Diagnostic posé <span>après élimination d'une pathologie alternative</span> (notamment <span>fissure ou suppuration</span>).</li>\n        <li><span>FR déclenchants</span> (inconstants) : <span><span class=\"nc-blue nc-bold\">diarrhée</span></span>, <span><span class=\"nc-blue nc-bold\">constipation</span></span>, <span><span class=\"nc-blue nc-bold\">effort de type dyschésie</span></span>, <span class=\"nc-blue nc-bold\">excès de table</span> (<span>alcool</span>, <span>plats épicés</span>).</li>\n        <li><span>Facteur aggravant</span> : <span>passage à la selle</span>, <span><span class=\"nc-red_bg\">exercice physique</span></span>.</li>\n        <li>Durée moyenne : <span><span class=\"nc-pink nc-bold\">24-72 h</span></span>.</li>\n        <li><span>Examen endoscopique</span> : <span class=\"nc-blue_bg\">aspect congestif</span>, œdémateux, <span class=\"nc-blue_bg\">parfois un semis de microthromboses</span>.</li>\n      </ul>\n\n      <h5><span class=\"nc-red nc-bold\">Thrombose hémorroïdaire interne</span></h5>\n      <ul>\n        <li>Beaucoup plus rare que la thrombose hémorroïdaire externe (sémiologie décrite à l'objectif « Connaître <span>les</span> modalités du diagnostic d'une thrombose hémorroïdaire »).</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 301 — Tumeur colon - rectum · 213 — Anémie</em></p></div>"},{"i":"6fe18b3915e2","n":288,"o":"288-12","u":"Etiologie","t":"Connaître les principaux facteurs favorisant la pathologie hémorroïdaire","q":"Quels sont les points essentiels concernant les principaux facteurs favorisant la pathologie hémorroïdaire ?","a":"<div class=\"notion-course\"><h5>Facteurs favorisants principaux</h5>\n      <ul>\n        <li><span><span class=\"nc-blue_bg\">Troubles du transit intestinal</span></span>, en particulier la <span>dyschésie</span>.</li>\n        <li><span>3ᵉ trimestre de grossesse</span>.</li>\n        <li><span>Accouchement</span>.</li>\n        <li><span><span class=\"nc-blue_bg\">Post-partum immédiat</span></span>.</li>\n      </ul>\n\n      <h5>Facteurs discutés (non établis)</h5>\n      <ul>\n        <li><span>Antécédents familiaux</span>.</li>\n        <li><span>Alimentation épicée</span>.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 283 — <span>Constipation</span></em></p></div>"},{"i":"81feabb10189","n":288,"o":"288-16","u":"Prise en charge","t":"Connaître les indications du traitement chirurgical","q":"Quels sont les points essentiels concernant les indications du traitement chirurgical ?","a":"<div class=\"notion-course\"><h5>Indications directes à la <span>chirurgie</span></h5>\n      <ul>\n        <li>Anémie ferriprive avec origine hémorroïdaire confirmée après bilan : discuter un traitement efficace selon sévérité et traitements déjà essayés ; ne pas attribuer automatiquement l’anémie aux hémorroïdes.</li>\n        <li><span class=\"nc-red nc-bold\">Prolapsus</span> thrombosé hyperalgique : avis spécialisé rapide, traitement médical et geste éventuel selon examen et évolution ; pas d’opération automatique de toute thrombose.</li>\n        <li>Thromboses hémorroïdaires externes <span>récidivantes</span>.</li>\n        <li><span>Pathologies proctologiques associées</span> nécessitant une intervention chirurgicale.</li>\n        <li>Marisques gênantes après évaluation et demande du patient : exérèse discutée ; leur seule présence n’impose pas une opération.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">📌 Dans l'algorithme par <span>grade de Goligher</span>, le <span>grade IV</span> (<span><span class=\"nc-red nc-bold\">prolapsus</span> irréductible</span>) a pour traitement de référence l'<span><span class=\"nc-pink_bg\">hémorroïdectomie</span></span>.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 213 — Anémie</em></p><div class=\"callout callout-info\"><strong>Précisions actualisées</strong><ul><li>Une marisque isolée ou un saignement ne suffit pas à imposer la chirurgie. Confirmer la cause, évaluer le retentissement et les traitements déjà essayés, puis discuter le geste avec le patient.</li></ul></div></div>"},{"i":"c6abf58062a9","n":288,"o":"288-17","u":"Suivi et / ou pronostic","t":"Connaître l’évolution spontanée de la thrombose hémorroïdaire externe","q":"Quels sont les points essentiels concernant l’évolution spontanée de la thrombose hémorroïdaire externe ?","a":"<div class=\"notion-course\"><h5>Évolutions spontanées possibles</h5>\n      <ul>\n        <li><span><span class=\"nc-green_bg\">Régression lente</span></span><span class=\"nc-green_bg\"> de la crise avec </span><span><span class=\"nc-green_bg\">rémission anatomique complète ad integrum</span></span> en <span><span class=\"nc-pink nc-bold\">5-15 jours</span></span>.</li>\n        <li><span><span class=\"nc-blue_bg\">Fistulisation à la peau</span></span> : se traduit par un <span><span class=\"nc-blue_bg\">saignement minime</span></span> et une régression / sédation des douleurs.</li>\n        <li><span class=\"nc-orange_bg\">Formation possible d'une </span><span><span class=\"nc-orange_bg\">marisque</span></span> : <span>repli mucocutané résiduel</span> lié à la distension cutanée par la thrombose, sans retour à une anatomie normale (<span><span class=\"nc-red nc-bold\">préjudice surtout esthétique</span></span>, rarement une indication de traitement).</li>\n      </ul>\n\n      <h5><span>Pronostic</span></h5>\n      <ul>\n        <li><span>Évolution</span> <span>bénigne dans tous les cas</span> : <span><span class=\"nc-green_bg\">pas de risque embolique</span></span>.</li>\n        <li><span>Complications suppuratives secondaires</span> exceptionnelles.</li>\n        <li><span>Récidives possibles</span>, y compris sur le même site.</li>\n      </ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/1cb37f85d94181d48f90d343ea1165e6?pvs=204","reviewedAt":"2026-10-16","batch":"digestive-infectious-50","verification":"reviewed","note":"Relecture et contrôles du lot réalisés. LiSA : copies locales ; ordinateur et format iPad simulé."}};
